type VerificationEvidencePhoto = { key: string; url: string; fileName: string; mimeType: "image/jpeg" | "image/png" | "image/webp" };
type RetroactiveReason = "verified_not_registered" | "technical_unavailability" | "other";
const RETROACTIVE_REASON_OPTIONS: Array<{ value: RetroactiveReason; label: string }> = [
  { value: "verified_not_registered", label: "Controlo verificado no dia agendado, mas não registado" },
  { value: "technical_unavailability", label: "Adiado por falta de disponibilidade técnica para verificação no dia agendado" },
  { value: "other", label: "Outra opção" },
];
const BPHF_CRITERIA = ["Estado de limpeza e conservação do fardamento", "Higienização das mãos dos manipuladores", "Cumprimento geral das regras de BPHF", "Estado de limpeza e organização dos cacifos do pessoal e de trabalho"] as const;
const BPHF_CRITERIA_HELP: Record<(typeof BPHF_CRITERIA)[number], string> = {
  "Estado de limpeza e conservação do fardamento": "Confirme que o fardamento está limpo, íntegro e adequado à função, sem sujidade visível ou danos que possam comprometer a higiene.",
  "Higienização das mãos dos manipuladores": "Observe se a lavagem e desinfeção das mãos é realizada nos momentos necessários, com técnica adequada e sem práticas que possam recontaminar as mãos.",
  "Cumprimento geral das regras de BPHF": "Avalie o cumprimento global das boas práticas aplicáveis à área, incluindo comportamento higiénico, prevenção de contaminação e organização do posto.",
  "Estado de limpeza e organização dos cacifos do pessoal e de trabalho": "Confirme que os cacifos pessoais e de trabalho estão limpos, organizados, sem objetos indevidos e adequados à prevenção de contaminação.",
};
const CONTROL_ICONS = { bphf: ShieldCheck, metal_detectors: Gauge, sensory: FlaskConical, shelf_life: PackageSearch, monthly_checklist: ClipboardCheck, suggestion_boxes: Lightbulb, fragile_items: Boxes, dispatch_control: Truck, internal_analysis: Microscope, temperature_controls: ThermometerSnowflake, food_defense: ShieldCheck } as const;

type FactoryOption = { id: number; name: string; code?: string };
type ControlFactoryScope = { factories: FactoryOption[]; factoryId: string; setFactoryId: (value: string) => void };
export const ControlFactoryContext = React.createContext<ControlFactoryScope>({ factories: [], factoryId: "", setFactoryId: () => undefined });
const useControlFactory = () => React.useContext(ControlFactoryContext);
type ModuleProgress = { expected: number; completed: number; registeredToday: number; pending: string[]; percentage: number };
type FactoryModuleProgress = { factoryId: number; expected: number; completed: number; registeredToday: number; percentage: number; pendingTaskId?: number };
const ModuleProgressContext = React.createContext<{ items: Record<string, ModuleProgress>; byFactory: Record<string, FactoryModuleProgress[]>; isLoading: boolean }>({ items: {}, byFactory: {}, isLoading: false });

function ModuleHeader({ label, description, icon: Icon, critical = false, commonToAllOperations = false, hideProgress = false, children }: { label: string; description: string; icon: typeof ClipboardCheck; critical?: boolean; commonToAllOperations?: boolean; hideProgress?: boolean; children?: React.ReactNode }) {
  const { factories, factoryId, setFactoryId } = useControlFactory();
  const helpAnchor = ({ "Verificação de BPHF": "bphf", "Verificação de detetores de metais": "metal_detectors", "Controlo sensorial de produto acabado": "sensory", "Controlo de amostras em shelf_life": "shelf_life", "Controlo de amostras em shelf-life": "shelf_life", "Checklist mensal": "monthly_checklist", "Caixas de sugestões": "suggestion_boxes", "Quebráveis": "fragile_items", "Controlo à expedição": "dispatch_control", "Análises internas": "internal_analysis", "Controlos de Temperatura": "temperature_controls", "Food Defense": "food_defense" } as Record<string, string>)[label] ?? "bphf";
  const selectClass = critical ? "border-red-200 bg-white text-red-900" : "border-slate-600 bg-slate-800 text-white [&>svg]:text-slate-300";
  const progressState = React.useContext(ModuleProgressContext);
  const progress = progressState.items[helpAnchor];
  const scheduledFactories = (progressState.byFactory[helpAnchor] ?? []).filter((item) => item.expected > 0).map((item) => ({ ...item, name: factories.find((factory) => factory.id === item.factoryId)?.name ?? "Fábrica" }));
  const progressValue = progress?.percentage ?? 0;

  return <header className={critical ? "rounded-2xl border border-red-200 bg-red-50 px-6 py-5" : "rounded-2xl bg-slate-900 px-6 py-5 text-white"}>
    <div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
      <div className="flex min-w-0 items-center gap-3"><Link href="/controlos"><Button variant={critical ? "outline" : "secondary"} size="icon" className={critical ? "border-red-200 bg-white text-red-800 hover:bg-red-100" : "bg-slate-800 text-white hover:bg-slate-700"}><ArrowLeft className="h-4 w-4" /></Button></Link><div className="flex min-w-0 items-center gap-3"><div className={critical ? "rounded-xl bg-red-100 p-3 text-red-700" : "rounded-xl bg-teal-500/15 p-3 text-teal-300"}><Icon className="h-6 w-6" /></div><div><p className={critical ? "font-mono-ui text-xs uppercase tracking-[0.17em] text-red-700" : "font-mono-ui text-xs uppercase tracking-[0.17em] text-teal-300"}>Registo operacional</p><h1 className="mt-1 text-2xl font-semibold tracking-tight">{label}</h1><p className={critical ? "mt-1 text-sm text-red-800" : "mt-1 text-sm text-slate-300"}>{description}</p></div></div></div>
      <div className="flex flex-col gap-2 sm:flex-row sm:items-stretch">{!commonToAllOperations && <div className={critical ? "rounded-xl border border-red-200 bg-white/80 p-3" : "rounded-xl border border-slate-700 bg-slate-800/70 p-3"}><div className="flex items-center gap-2"><Factory className={critical ? "h-4 w-4 text-red-700" : "h-4 w-4 text-teal-300"} /><span className={critical ? "text-xs font-medium text-red-800" : "text-xs font-medium text-slate-200"}>Fábrica / linha</span></div><Select value={factoryId} onValueChange={setFactoryId}><SelectTrigger className={`mt-2 w-full min-w-60 ${selectClass}`}><SelectValue placeholder="Selecione a fábrica" /></SelectTrigger><SelectContent>{factories.map((factory) => <SelectItem key={factory.id} value={String(factory.id)}>{factory.name}</SelectItem>)}</SelectContent></Select></div>}<Link href={`/ajuda#${helpAnchor}`}><Button variant={critical ? "outline" : "secondary"} className={critical ? "border-red-200 bg-white text-red-800 hover:bg-red-100" : "bg-slate-800 text-white hover:bg-slate-700"}><CircleHelp className="mr-2 h-4 w-4" />Ajuda</Button></Link></div>
    </div>
    {children}
    {!hideProgress && <div className={critical ? "mt-5 rounded-xl border border-red-200 bg-white/80 p-4" : "mt-5 rounded-xl border border-slate-700 bg-slate-800/70 p-4"} aria-label="Evolução do preenchimento por fábrica"><div className="flex items-center justify-between gap-4"><span className={critical ? "text-sm font-medium text-red-900" : "text-sm font-medium text-white"}>{commonToAllOperations ? "Preenchimento do controlo comum" : "Preenchimento por fábrica"}</span>{commonToAllOperations && <span className={critical ? "font-mono-ui text-sm text-red-800" : "font-mono-ui text-sm text-teal-300"}>{progressState.isLoading ? "A calcular…" : `${progressValue}%`}</span>}</div>{progressState.isLoading ? <p className={critical ? "mt-3 text-xs text-red-800" : "mt-3 text-xs text-slate-300"}>A obter os controlos agendados…</p> : commonToAllOperations ? <><Progress value={progressValue} className="mt-3 h-2" /><p className={critical ? "mt-2 text-xs text-red-800" : "mt-2 text-xs text-slate-300"}>{progress?.expected ? `${progress.completed} de ${progress.expected} verificações concluídas` : "Sem controlos agendados"}</p></> : scheduledFactories.length ? <div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{scheduledFactories.map((item) => <div key={item.factoryId} className={critical ? "rounded-xl border border-red-100 bg-white p-3" : "rounded-xl border border-slate-700 bg-slate-900/50 p-3"}><div className="flex items-center justify-between gap-3"><p className={critical ? "text-sm font-medium text-red-950" : "text-sm font-medium text-white"}>{item.name}</p><span className={critical ? "font-mono-ui text-sm text-red-800" : "font-mono-ui text-sm text-teal-300"}>{item.percentage}%</span></div><Progress value={item.percentage} className="mt-3 h-2" /><p className={critical ? "mt-2 text-xs text-red-800" : "mt-2 text-xs text-slate-300"}>{item.completed} de {item.expected} controlo{item.expected === 1 ? "" : "s"} concluído{item.completed === 1 ? "" : "s"}</p></div>)}</div> : <p className={critical ? "mt-3 text-sm text-red-800" : "mt-3 text-sm text-slate-300"}>Sem controlos agendados</p>}</div>}
  </header>;
}

function Notes({ value, onChange, required = false }: { value: string; onChange: (value: string) => void; required?: boolean }) { return <div className="space-y-2"><Label>Observações {required ? "(obrigatórias)" : ""}</Label><Textarea value={value} required={required} onChange={(event) => onChange(event.target.value)} placeholder="Registe observações, evidências ou contexto relevante." /></div>; }

function NcEvidenceUploader({ module, photos, onChange }: { module: (typeof MODULES)[number]["id"]; photos: VerificationEvidencePhoto[]; onChange: (photos: VerificationEvidencePhoto[]) => void }) {
  const { factoryId } = useControlFactory();
  const upload = trpc.quality.uploadVerificationEvidence.useMutation({ onError: (error) => toast.error(error.message) });
  async function uploadPhoto(file?: File) {
    if (!file) return;
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return toast.error("Use uma imagem JPG, PNG ou WEBP.");
    if (file.size > 4_500_000) return toast.error("A fotografia deve ter no máximo 4,5 MB.");
    try {
      const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Não foi possível ler a fotografia.")); reader.readAsDataURL(file); });
      upload.mutate({ module, factoryId: factoryId ? Number(factoryId) : null, fileName: file.name, mimeType: file.type as VerificationEvidencePhoto["mimeType"], dataUrl }, { onSuccess: (photo) => { onChange([...photos, photo]); toast.success("Fotografia da incidência adicionada."); } });
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível carregar a fotografia."); }
  }
  return <div className="space-y-3 rounded-xl border border-dashed border-red-200 bg-red-50/60 p-4"><div><Label>Fotografia da incidência</Label><p className="mt-1 text-xs leading-5 text-red-900">Anexe fotografias do desvio ou da incidência. Formatos JPG, PNG ou WEBP até 4,5 MB.</p></div><Input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => uploadPhoto(event.target.files?.[0])} disabled={upload.isPending} />{photos.length > 0 && <div className="grid grid-cols-2 gap-2">{photos.map((photo) => <div key={photo.url} className="relative"><img src={photo.url} alt={`Evidência da incidência: ${photo.fileName}`} className="h-24 w-full rounded-lg border border-red-100 object-cover" /><Button type="button" size="icon" variant="secondary" className="absolute -right-2 -top-2 h-5 w-5 rounded-full" aria-label={`Remover ${photo.fileName}`} onClick={() => onChange(photos.filter((item) => item.url !== photo.url))}><Trash2 className="h-3 w-3" /></Button></div>)}</div>}</div>;
}

function ControlAccessBlocked({ module, label, description, reason, isLoading }: { module: keyof typeof CONTROL_ICONS; label: string; description: string; reason: string; isLoading: boolean }) {
  const Icon = CONTROL_ICONS[module];
  const commonToAllOperations = module === "dispatch_control" || module === "internal_analysis";
  return <><ModuleHeader label={label} description={description} icon={Icon} critical={module === "metal_detectors"} commonToAllOperations={commonToAllOperations} /><Card className="border border-amber-200 bg-amber-50/80 shadow-sm"><CardContent className="flex flex-col gap-4 p-6 sm:flex-row sm:items-start"><div className="rounded-xl bg-amber-100 p-3 text-amber-800"><CircleAlert className="h-6 w-6" /></div><div><p className="font-semibold text-amber-950">Preenchimento indisponível</p><p className="mt-1 max-w-2xl text-sm leading-6 text-amber-900">{isLoading ? "A confirmar a autorização do Plano do Dia…" : reason}</p><p className="mt-3 text-sm text-amber-800">A Responsável de Qualidade deve publicar o controlo, atribuir-lhe um responsável e selecionar a fábrica ou linha aplicável antes do preenchimento.</p></div></CardContent></Card></>;
}

function PreviousPlanNotice({ dueAt, performedDate, onPerformedDateChange, reason, onReasonChange, justification, onJustificationChange }: { dueAt: Date | string | null | undefined; performedDate: string; onPerformedDateChange: (value: string) => void; reason: RetroactiveReason | ""; onReasonChange: (value: RetroactiveReason) => void; justification: string; onJustificationChange: (value: string) => void }) {
  if (!dueAt) return null;
  const plannedDate = new Date(dueAt);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (plannedDate >= today) return null;
  const toDateInputValue = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  return <Card className="border-2 border-amber-300 bg-amber-50 shadow-sm"><CardContent className="space-y-4 p-5"><div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_14rem]"><div className="flex items-start gap-3"><div className="rounded-xl bg-amber-200 p-3 text-amber-950"><CalendarClock className="h-5 w-5" /></div><div><p className="font-mono-ui text-xs font-bold uppercase tracking-[0.16em] text-amber-900">Controlo retroativo</p><p className="mt-1 font-semibold text-amber-950">Este controlo é relativo ao dia <span className="inline-flex rounded-md bg-amber-200 px-2 py-0.5 font-mono-ui text-base font-bold text-amber-950">{plannedDate.toLocaleDateString("pt-PT")}</span></p><p className="mt-2 max-w-2xl text-sm leading-6 text-amber-900">Está a preencher verificações previstas para esta data, e não para o dia atual. A data prevista será mantida no registo.</p></div></div><div className="w-full space-y-2"><Label className="font-semibold text-amber-950">Data de realização</Label><Input required type="date" min={toDateInputValue(plannedDate)} max={toDateInputValue(today)} value={performedDate} onChange={(event) => onPerformedDateChange(event.target.value)} className="border-amber-300 bg-white text-slate-950" /></div></div><div className="rounded-xl border border-amber-200 bg-white/70 p-4"><Label className="font-semibold text-amber-950">Justificação do preenchimento fora da data prevista</Label><Select value={reason} onValueChange={(value) => onReasonChange(value as RetroactiveReason)}><SelectTrigger className="mt-2 border-amber-300 bg-white text-slate-950"><SelectValue placeholder="Selecione a justificação obrigatória" /></SelectTrigger><SelectContent>{RETROACTIVE_REASON_OPTIONS.map((option) => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select>{reason === "other" && <div className="mt-3 space-y-2"><Label className="text-amber-950">Indique a justificação</Label><Textarea required value={justification} onChange={(event) => onJustificationChange(event.target.value)} placeholder="Descreva o motivo do preenchimento fora da data prevista." className="border-amber-300 bg-white text-slate-950" /></div>}</div></CardContent></Card>;
}

export default function ModuleControl() {
  const [, params] = useRoute("/controlos/:module");
  const module = params?.module ?? "bphf";
  const config = MODULES.find((item) => item.id === module);
  const metadata = trpc.quality.metadata.useQuery();
  const bphfAreas = Array.from(new Set(metadata.data?.areas.filter((area) => area.group === "bphf").map((area) => area.name) ?? []));
  const factories = metadata.data?.factories ?? [];
  const [factoryId, setFactoryId] = useState(() => new URLSearchParams(window.location.search).get("factoryId") ?? readControlFactoryScope());
  const metalAreasForFactory = factoryId ? metadata.data?.areas.filter((area) => area.group === "metal" && area.factoryId === Number(factoryId)).map((area) => area.name) ?? [] : [];
  useEffect(() => { writeControlFactoryScope(factoryId); }, [factoryId]);
  const bphfAreasForFactory = factoryId ? metadata.data?.areas.filter((area) => area.group === "bphf" && area.factoryId === Number(factoryId) && ["Embalagem", "Limpeza", "Produção"].includes(area.name)).map((area) => area.name) ?? [] : [];
  const isSharedControl = module === "dispatch_control" || module === "internal_analysis";
  const plannedTaskId = Number(new URLSearchParams(window.location.search).get("plannedTaskId")) || undefined;
  const authorization = trpc.quality.controlAuthorization?.useQuery?.({ module: (config?.id ?? "bphf") as (typeof MODULES)[number]["id"], factoryId: isSharedControl ? undefined : factoryId ? Number(factoryId) : undefined, plannedTaskId }) ?? { data: undefined, isLoading: false };
  const progressDateInput = useMemo(() => {
    const dueAt = authorization.data?.isPreviousPending ? authorization.data.dueAt : undefined;
    if (dueAt) {
      const plannedDate = new Date(dueAt);
      return new Date(plannedDate.getFullYear(), plannedDate.getMonth(), plannedDate.getDate(), 12);
    }
    const today = new Date();
    return new Date(today.getFullYear(), today.getMonth(), today.getDate(), 12);
  }, [authorization.data?.dueAt, authorization.data?.isPreviousPending]);
  const dashboard = trpc.quality.dashboard.useQuery({ date: progressDateInput });
  const utils = trpc.useUtils();
  const [performedDate, setPerformedDate] = useState("");
  const [retroactiveReason, setRetroactiveReason] = useState<RetroactiveReason | "">("");
  const [retroactiveJustification, setRetroactiveJustification] = useState("");
  useEffect(() => { if (authorization.data?.isPreviousPending && authorization.data.dueAt) { const date = new Date(authorization.data.dueAt); setPerformedDate(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`); } else { setPerformedDate(""); setRetroactiveReason(""); setRetroactiveJustification(""); } }, [authorization.data?.dueAt, authorization.data?.isPreviousPending]);
  const createEntry = trpc.quality.createEntry.useMutation({ onSuccess: (data) => { utils.quality.dashboard.invalidate(); utils.quality.reports.invalidate(); utils.quality.listNcs.invalidate(); utils.quality.fragilePending.invalidate(); toast[data.critical ? "error" : "success"](data.critical ? "Incidência crítica registada. Crie uma Não Conformidade no formulário próprio se necessário." : "Controlo registado com sucesso."); }, onError: (error) => toast.error(error.message) });
  if (!config) return <div className="p-8">Módulo não encontrado.</div>;
  const withRetroactiveJustification = (input: any) => {
    if (!authorization.data?.isPreviousPending) return input;
    if (!retroactiveReason) { toast.error("Selecione a justificação do preenchimento fora da data prevista."); return null; }
    if (retroactiveReason === "other" && !retroactiveJustification.trim()) { toast.error("Indique a justificação para a opção selecionada."); return null; }
    return { ...input, performedAt: performedDate, retroactiveReason, retroactiveJustification: retroactiveReason === "other" ? retroactiveJustification.trim() : undefined };
  };
  const scopedCreateEntry = {
    isPending: createEntry.isPending,
    mutate: (input: any) => { const datedInput = withRetroactiveJustification(input); if (!datedInput) return; const taskInput = authorization.data?.taskId ? { ...datedInput, plannedTaskId: authorization.data.taskId } : datedInput; if (isSharedControl) return createEntry.mutate(taskInput); if (!factoryId) return toast.error("Selecione a fábrica ou linha antes de registar o controlo."); createEntry.mutate({ ...taskInput, factoryId: Number(factoryId) }); },
    mutateAsync: async (input: any) => { const datedInput = withRetroactiveJustification(input); if (!datedInput) throw new Error("Justificação retroativa obrigatória"); const taskInput = authorization.data?.taskId ? { ...datedInput, plannedTaskId: authorization.data.taskId } : datedInput; if (isSharedControl) return createEntry.mutateAsync(taskInput); if (!factoryId) { toast.error("Selecione a fábrica ou linha antes de registar o controlo."); throw new Error("Fábrica obrigatória"); } return createEntry.mutateAsync({ ...taskInput, factoryId: Number(factoryId) }); },
  };
  const props = { createEntry: scopedCreateEntry, plannedTaskId: authorization.data?.taskId };
  if (authorization.isLoading || (authorization.data && !authorization.data.allowed)) return <ControlFactoryContext.Provider value={{ factories, factoryId, setFactoryId }}><ModuleProgressContext.Provider value={{ items: (dashboard.data?.moduleProgress as Record<string, ModuleProgress> | undefined) ?? {}, byFactory: (dashboard.data?.moduleProgressByFactory as Record<string, FactoryModuleProgress[]> | undefined) ?? {}, isLoading: dashboard.isLoading }}><div className="app-grid min-h-full -m-4 p-4 md:-m-6 md:p-6"><section className="mx-auto max-w-5xl space-y-6"><ControlAccessBlocked module={(config.id as keyof typeof CONTROL_ICONS)} label={config.label} description={config.description} reason={authorization.data?.reason ?? "A confirmar a autorização do Plano do Dia."} isLoading={authorization.isLoading} /></section></div></ModuleProgressContext.Provider></ControlFactoryContext.Provider>;
  return <ControlFactoryContext.Provider value={{ factories, factoryId, setFactoryId }}><ModuleProgressContext.Provider value={{ items: (dashboard.data?.moduleProgress as Record<string, ModuleProgress> | undefined) ?? {}, byFactory: (dashboard.data?.moduleProgressByFactory as Record<string, FactoryModuleProgress[]> | undefined) ?? {}, isLoading: dashboard.isLoading }}><div className="app-grid min-h-full -m-4 p-4 md:-m-6 md:p-6"><section className="mx-auto max-w-5xl space-y-6"><PreviousPlanNotice dueAt={authorization.data?.isPreviousPending ? authorization.data.dueAt : null} performedDate={performedDate} onPerformedDateChange={setPerformedDate} reason={retroactiveReason} onReasonChange={setRetroactiveReason} justification={retroactiveJustification} onJustificationChange={setRetroactiveJustification} />{module === "bphf" && <Bphf {...props} areas={bphfAreasForFactory} />}{module === "metal_detectors" && <MetalDetectors {...props} areas={metalAreasForFactory} />}{module === "sensory" && <Sensory {...props} areas={bphfAreas} />}{module === "shelf_life" && <ShelfLife {...props} areas={bphfAreas} />}{module === "monthly_checklist" && <MonthlyChecklistV2 {...props} />}{module === "suggestion_boxes" && <SuggestionBoxes {...props} factoryId={factoryId} />}{module === "fragile_items" && <><ModuleHeader label="Quebráveis" description="Inspecione os pontos por periodicidade, área e estado de integridade." icon={Boxes} /><FragileOperationsPanel {...props} factoryId={factoryId} showHeader={false} /></>}{module === "dispatch_control" && <DispatchControl />}{module === "internal_analysis" && <InternalAnalysis {...props} />}{module === "temperature_controls" && <TemperatureControls {...props} />}{module === "food_defense" && <FoodDefense {...props} />}</section></div></ModuleProgressContext.Provider></ControlFactoryContext.Provider>;
}

function BphfLegacy({ createEntry, areas }: any) {
  const { factoryId } = useControlFactory();
  const areaSignature = areas.join("|");
  const employees = trpc.quality.listBphfInspectionEmployees.useQuery();
  const utils = trpc.useUtils();
  const [areasByCriterion, setAreasByCriterion] = useState<Record<string, string>>({});
  const [collaboratorsByCriterion, setCollaboratorsByCriterion] = useState<Record<string, string>>({});
  const [results, setResults] = useState<Record<string, Result | "">>(() => Object.fromEntries(BPHF_CRITERIA.map((item) => [item, ""])));
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [registered, setRegistered] = useState<Record<string, boolean>>({});
  const [employeeDialogOpen, setEmployeeDialogOpen] = useState(false);
  const [newEmployeeName, setNewEmployeeName] = useState("");
  const [criterionForEmployee, setCriterionForEmployee] = useState<string | null>(null);
  const [inspectionFilter, setInspectionFilter] = useState("all");
  const [resultFilter, setResultFilter] = useState("all");
  const inspectionInput = useMemo(() => ({ collaboratorId: inspectionFilter === "all" ? undefined : Number(inspectionFilter), factoryId: factoryId ? Number(factoryId) : undefined, result: resultFilter === "all" ? undefined : resultFilter as Result }), [factoryId, inspectionFilter, resultFilter]);
  const inspections = trpc.quality.listBphfCollaboratorInspections.useQuery(inspectionInput, { enabled: Boolean(factoryId) });
  const addEmployee = trpc.quality.addBphfInspectionEmployee.useMutation({ onSuccess: (employee) => { utils.quality.listBphfInspectionEmployees.invalidate(); if (criterionForEmployee) setCollaboratorsByCriterion((current) => ({ ...current, [criterionForEmployee]: String(employee.id) })); setNewEmployeeName(""); setCriterionForEmployee(null); setEmployeeDialogOpen(false); toast.success(employee.alreadyExists ? "Colaborador já constava na lista e foi selecionado." : "Colaborador adicionado à lista de inspeção."); }, onError: (error) => toast.error(error.message) });
  useEffect(() => { setAreasByCriterion({}); setCollaboratorsByCriterion({}); setResults(Object.fromEntries(BPHF_CRITERIA.map((item) => [item, ""]))); setNotes({}); setRegistered({}); }, [areaSignature]);
  const openEmployeeDialog = (criterion: string) => { setCriterionForEmployee(criterion); setNewEmployeeName(""); setEmployeeDialogOpen(true); };
  async function registerCriterion(criterion: (typeof BPHF_CRITERIA)[number]) { const area = areasByCriterion[criterion]; const collaboratorId = collaboratorsByCriterion[criterion]; const result = results[criterion]; const collaborator = employees.data?.find((item) => String(item.id) === collaboratorId); if (!area) return toast.error("Selecione a área verificada neste ponto."); if (!collaborator) return toast.error("Selecione o colaborador inspecionado neste ponto."); if (!result) return toast.error("Selecione C, NC ou N/A antes de registar este ponto."); if (result === "NC" && !notes[criterion]?.trim()) return toast.error("Inclua uma observação para o resultado NC."); await createEntry.mutateAsync({ module: "bphf", title: criterion, area, result, notes: notes[criterion] || undefined, payload: { criterion, collaboratorId: collaborator.id, collaboratorName: collaborator.name }, createNonconformity: false, severity: "medium" }); setRegistered((current) => ({ ...current, [criterion]: true })); utils.quality.listBphfCollaboratorInspections.invalidate(); toast.success(`Ponto BPHF registado para ${collaborator.name}.`); }
  return <><ModuleHeader label="Verificação de BPHF" description="Registe cada ponto de BPHF de forma independente, identificando a área e o colaborador inspecionado." icon={ShieldCheck} /><div className="rounded-2xl border border-teal-100 bg-teal-50/70 p-5"><p className="font-medium text-teal-950">Registo por ponto verificado</p><p className="mt-1 text-sm text-teal-800">Cada ponto pode ser avaliado numa área diferente e em momentos distintos. Não existe uma resposta pré-selecionada: escolha sempre C, NC ou N/A antes de registar.</p></div><div className="space-y-5">{BPHF_CRITERIA.map((criterion, index) => { const result = results[criterion]; return <Card key={criterion} className="border-0 panel-shadow"><CardContent className="space-y-5 p-5"><div className="flex items-start justify-between gap-4"><div className="flex items-start gap-3"><span className="font-mono-ui rounded-lg bg-teal-50 px-2 py-1 text-xs font-semibold text-teal-700">{String(index + 1).padStart(2, "0")}</span><div><div className="flex items-start gap-1.5"><p className="font-medium">{criterion}</p><ContextualHelpIcon label={`Explicação do critério BPHF: ${criterion}`} className="mt-0.5 shrink-0">{BPHF_CRITERIA_HELP[criterion]}</ContextualHelpIcon></div><p className="mt-1 text-sm text-muted-foreground">Preencha apenas quando este ponto for efetivamente verificado.</p></div></div>{registered[criterion] && <Badge className="bg-emerald-100 text-emerald-800 hover:bg-emerald-100">Registado</Badge>}</div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Área verificada</Label><Select value={areasByCriterion[criterion] ?? ""} onValueChange={(value) => setAreasByCriterion((current) => ({ ...current, [criterion]: value }))} disabled={!areas.length}><SelectTrigger><SelectValue placeholder={areas.length ? "Selecione a área" : "Selecione primeiro a fábrica"} /></SelectTrigger><SelectContent>{areas.map((item: string) => <SelectItem value={item} key={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Colaborador inspecionado</Label><div className="flex gap-2"><Select value={collaboratorsByCriterion[criterion] ?? ""} onValueChange={(value) => setCollaboratorsByCriterion((current) => ({ ...current, [criterion]: value }))}><SelectTrigger><SelectValue placeholder="Selecione o colaborador" /></SelectTrigger><SelectContent>{employees.data?.map((employee) => <SelectItem key={employee.id} value={String(employee.id)}>{employee.name}</SelectItem>)}</SelectContent></Select><Button type="button" variant="outline" size="icon" aria-label={`Adicionar colaborador para ${criterion}`} onClick={() => openEmployeeDialog(criterion)}><Plus className="h-4 w-4" /></Button></div></div></div><div className="space-y-2"><Label>Resultado</Label><div className="grid grid-cols-3 gap-2">{(["C", "NC", "N/A"] as Result[]).map((option) => <Button key={option} type="button" variant={result === option ? (option === "NC" ? "destructive" : "default") : "outline"} onClick={() => setResults((current) => ({ ...current, [criterion]: option }))}>{option}</Button>)}</div></div><Notes value={notes[criterion] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [criterion]: value }))} required={result === "NC"} /><Button type="button" className="w-full" disabled={createEntry.isPending || !areasByCriterion[criterion] || !collaboratorsByCriterion[criterion] || !result} variant={result === "NC" ? "destructive" : "default"} onClick={() => registerCriterion(criterion)}>{createEntry.isPending ? "A registar…" : registered[criterion] ? "Registar nova verificação deste ponto" : "Registar ponto verificado"}</Button></CardContent></Card>; })}</div><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Colaboradores inspecionados</CardTitle><CardDescription>Filtre os registos BPHF para consultar rapidamente o colaborador, o ponto avaliado e o resultado.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 md:grid-cols-2"><Select value={inspectionFilter} onValueChange={setInspectionFilter}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os colaboradores</SelectItem>{employees.data?.map((employee) => <SelectItem key={employee.id} value={String(employee.id)}>{employee.name}</SelectItem>)}</SelectContent></Select><Select value={resultFilter} onValueChange={setResultFilter}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os resultados</SelectItem><SelectItem value="C">Conforme (C)</SelectItem><SelectItem value="NC">Não Conforme (NC)</SelectItem><SelectItem value="N/A">Não aplicável (N/A)</SelectItem></SelectContent></Select></div>{!factoryId ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Selecione a fábrica no cabeçalho para consultar os colaboradores inspecionados.</p> : inspections.isLoading ? <p className="text-sm text-muted-foreground">A carregar registos…</p> : inspections.data?.length ? <div className="divide-y overflow-hidden rounded-xl border border-slate-100">{inspections.data.map((inspection) => <div key={inspection.id} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium">{inspection.collaboratorName}</p><p className="mt-1 text-sm text-muted-foreground">{inspection.criterion} · {inspection.area}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(inspection.completedAt).toLocaleString("pt-PT")}</p></div><Badge className={inspection.result === "NC" ? "bg-red-600 text-white hover:bg-red-600" : inspection.result === "C" ? "bg-emerald-100 text-emerald-800 hover:bg-emerald-100" : "bg-slate-100 text-slate-700 hover:bg-slate-100"}>{inspection.result}</Badge></div>)}</div> : <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Não existem registos com os filtros selecionados.</p>}</CardContent></Card><Dialog open={employeeDialogOpen} onOpenChange={setEmployeeDialogOpen}><DialogContent><DialogHeader><DialogTitle>Adicionar colaborador inspecionado</DialogTitle><DialogDescription>O colaborador ficará disponível para todos os pontos de verificação BPHF.</DialogDescription></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Nome do colaborador</Label><Input value={newEmployeeName} onChange={(event) => setNewEmployeeName(event.target.value)} placeholder="Nome completo" /></div><Button className="w-full" disabled={!newEmployeeName.trim() || addEmployee.isPending} onClick={() => addEmployee.mutate({ name: newEmployeeName })}>{addEmployee.isPending ? "A adicionar…" : "Adicionar colaborador"}</Button></div></DialogContent></Dialog></>;
}

export function Bphf({ createEntry, areas }: any) {
  const { factoryId } = useControlFactory();
  const employees = trpc.quality.listBphfInspectionEmployees.useQuery();
  const utils = trpc.useUtils();
  const [areasByCriterion, setAreasByCriterion] = useState<Record<string, string>>({});
  const [collaboratorsByCriterion, setCollaboratorsByCriterion] = useState<Record<string, string>>({});
  const [results, setResults] = useState<Record<string, Result | "">>(() => Object.fromEntries(BPHF_CRITERIA.map((criterion) => [criterion, ""])));
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [evidenceByCriterion, setEvidenceByCriterion] = useState<Record<string, VerificationEvidencePhoto[]>>({});
  const [employeeDialogOpen, setEmployeeDialogOpen] = useState(false);
  const [newEmployeeName, setNewEmployeeName] = useState("");
  const [criterionForEmployee, setCriterionForEmployee] = useState<string | null>(null);
  const [inspectionFilter, setInspectionFilter] = useState("all");
  const [resultFilter, setResultFilter] = useState("all");
  const inspectionInput = useMemo(() => ({ collaboratorId: inspectionFilter === "all" ? undefined : Number(inspectionFilter), factoryId: factoryId ? Number(factoryId) : undefined, result: resultFilter === "all" ? undefined : resultFilter as Result }), [factoryId, inspectionFilter, resultFilter]);
  const inspections = trpc.quality.listBphfCollaboratorInspections.useQuery(inspectionInput, { enabled: Boolean(factoryId) });
  const todayKey = new Date().toISOString().slice(0, 10);
  const completedAreasByCriterion = useMemo(() => BPHF_CRITERIA.reduce((accumulator, criterion) => {
    accumulator[criterion] = new Set((inspections.data ?? []).filter((inspection) => inspection.criterion === criterion && new Date(inspection.completedAt).toISOString().slice(0, 10) === todayKey).map((inspection) => inspection.area));
    return accumulator;
  }, {} as Record<string, Set<string>>), [inspections.data, todayKey]);
  const addEmployee = trpc.quality.addBphfInspectionEmployee.useMutation({ onSuccess: (employee) => { utils.quality.listBphfInspectionEmployees.invalidate(); if (criterionForEmployee) setCollaboratorsByCriterion((current) => ({ ...current, [criterionForEmployee]: String(employee.id) })); setNewEmployeeName(""); setCriterionForEmployee(null); setEmployeeDialogOpen(false); toast.success(employee.alreadyExists ? "Colaborador já constava na lista e foi selecionado." : "Colaborador adicionado à lista de inspeção."); }, onError: (error) => toast.error(error.message) });

  useEffect(() => { setAreasByCriterion({}); setCollaboratorsByCriterion({}); setResults(Object.fromEntries(BPHF_CRITERIA.map((criterion) => [criterion, ""]))); setNotes({}); setEvidenceByCriterion({}); }, [factoryId, areas.join("|")]);

  const openEmployeeDialog = (criterion: string) => { setCriterionForEmployee(criterion); setNewEmployeeName(""); setEmployeeDialogOpen(true); };
  async function registerCriterion(criterion: (typeof BPHF_CRITERIA)[number]) {
    const area = areasByCriterion[criterion];
    const collaboratorId = collaboratorsByCriterion[criterion];
    const result = results[criterion];
    const collaborator = employees.data?.find((employee) => String(employee.id) === collaboratorId);
    if (!area) return toast.error("Selecione a área verificada neste ponto.");
    if (completedAreasByCriterion[criterion]?.has(area)) return toast.error("Esta área já foi registada hoje para este ponto. Selecione uma área pendente.");
    if (!collaborator) return toast.error("Selecione o colaborador inspecionado neste ponto.");
    if (!result) return toast.error("Selecione C, NC ou N/A antes de registar este ponto.");
    if (result === "NC" && !notes[criterion]?.trim()) return toast.error("Inclua uma observação para o resultado NC.");
    await createEntry.mutateAsync({ module: "bphf", title: criterion, area, result, notes: notes[criterion] || undefined, payload: { criterion, collaboratorId: collaborator.id, collaboratorName: collaborator.name, evidencePhotos: evidenceByCriterion[criterion] ?? [] }, createNonconformity: false, severity: "medium" });
    setAreasByCriterion((current) => ({ ...current, [criterion]: "" }));
    setCollaboratorsByCriterion((current) => ({ ...current, [criterion]: "" }));
    setResults((current) => ({ ...current, [criterion]: "" }));
    setNotes((current) => ({ ...current, [criterion]: "" }));
    setEvidenceByCriterion((current) => ({ ...current, [criterion]: [] }));
    utils.quality.listBphfCollaboratorInspections.invalidate();
    toast.success(`Área ${area} registada para ${collaborator.name}.`);
  }

  return <>
    <ModuleHeader label="Verificação de BPHF" description="Registe cada ponto por área e colaborador. Um ponto só fica concluído quando todas as áreas previstas estiverem verificadas." icon={ShieldCheck} />
    <Card className="border border-teal-100 bg-teal-50/70 shadow-sm"><CardContent className="grid gap-4 p-5 md:grid-cols-2"><div><p className="font-semibold text-teal-950">Conclusão por área</p><p className="mt-1 text-sm leading-6 text-teal-900">O estado «Concluído» só aparece quando todas as áreas da fábrica selecionada foram registadas para o respetivo ponto.</p></div><div className="flex flex-wrap items-center gap-2 text-xs"><Badge className="bg-emerald-100 text-emerald-800 hover:bg-emerald-100">Área concluída</Badge><Badge className="bg-amber-100 text-amber-900 hover:bg-amber-100">Área pendente</Badge><span className="text-teal-800">Os campos ficam sempre vazios até serem escolhidos manualmente.</span></div></CardContent></Card>
    <div className="space-y-5">{BPHF_CRITERIA.map((criterion, index) => {
      const completedAreas = completedAreasByCriterion[criterion] ?? new Set<string>();
      const pendingAreas = areas.filter((area: string) => !completedAreas.has(area));
      const complete = Boolean(areas.length) && pendingAreas.length === 0;
      const result = results[criterion];
      return <Card key={criterion} className={`border-0 panel-shadow ${complete ? "ring-1 ring-emerald-200" : "ring-1 ring-amber-100"}`}><CardContent className="space-y-5 p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div className="flex items-start gap-3"><span className={`font-mono-ui rounded-lg px-2 py-1 text-xs font-semibold ${complete ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-800"}`}>{String(index + 1).padStart(2, "0")}</span><div><div className="flex items-start gap-1.5"><p className="font-medium">{criterion}</p><ContextualHelpIcon label={`Explicação do critério BPHF: ${criterion}`} className="mt-0.5 shrink-0">{BPHF_CRITERIA_HELP[criterion]}</ContextualHelpIcon></div><p className="mt-1 text-sm text-muted-foreground">{complete ? "Todas as áreas previstas foram verificadas hoje." : `${pendingAreas.length} de ${areas.length || 0} área(s) ainda por verificar.`}</p></div></div><Badge className={complete ? "bg-emerald-100 text-emerald-800 hover:bg-emerald-100" : "bg-amber-100 text-amber-900 hover:bg-amber-100"}>{complete ? "Concluído" : "Em preenchimento"}</Badge></div>
        {areas.length ? <div className="flex flex-wrap gap-2 rounded-xl border border-slate-100 bg-slate-50/70 p-3">{areas.map((area: string) => <span key={area} className={`rounded-full px-3 py-1.5 text-xs font-medium ${completedAreas.has(area) ? "bg-emerald-100 text-emerald-800" : "bg-amber-100 text-amber-900"}`}>{completedAreas.has(area) ? "✓ " : "• "}{area}</span>)}</div> : <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Selecione a fábrica ou linha no cabeçalho para carregar as áreas BPHF.</p>}
        {!complete && <><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Área verificada</Label><Select value={areasByCriterion[criterion] ?? ""} onValueChange={(value) => setAreasByCriterion((current) => ({ ...current, [criterion]: value }))} disabled={!pendingAreas.length}><SelectTrigger><SelectValue placeholder={pendingAreas.length ? "Selecione uma área pendente" : "Sem áreas pendentes"} /></SelectTrigger><SelectContent>{pendingAreas.map((area: string) => <SelectItem value={area} key={area}>{area}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Colaborador inspecionado</Label><div className="flex gap-2"><Select value={collaboratorsByCriterion[criterion] ?? ""} onValueChange={(value) => setCollaboratorsByCriterion((current) => ({ ...current, [criterion]: value }))}><SelectTrigger><SelectValue placeholder="Selecione o colaborador" /></SelectTrigger><SelectContent>{employees.data?.map((employee) => <SelectItem key={employee.id} value={String(employee.id)}>{employee.name}</SelectItem>)}</SelectContent></Select><Button type="button" variant="outline" size="icon" aria-label={`Adicionar colaborador para ${criterion}`} onClick={() => openEmployeeDialog(criterion)}><Plus className="h-4 w-4" /></Button></div></div></div><div className="space-y-2"><Label>Resultado</Label><div className="grid grid-cols-3 gap-2">{(["C", "NC", "N/A"] as Result[]).map((option) => <Button key={option} type="button" variant={result === option ? (option === "NC" ? "destructive" : "default") : "outline"} onClick={() => setResults((current) => ({ ...current, [criterion]: option }))}>{option}</Button>)}</div></div><Notes value={notes[criterion] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [criterion]: value }))} required={result === "NC"} />{result === "NC" && <NcEvidenceUploader module="bphf" photos={evidenceByCriterion[criterion] ?? []} onChange={(photos) => setEvidenceByCriterion((current) => ({ ...current, [criterion]: photos }))} />}<Button type="button" className="w-full" disabled={createEntry.isPending || !areasByCriterion[criterion] || !collaboratorsByCriterion[criterion] || !result} variant={result === "NC" ? "destructive" : "default"} onClick={() => registerCriterion(criterion)}>{createEntry.isPending ? "A registar…" : "Registar área verificada"}</Button></>}
      </CardContent></Card>;
    })}</div>
    <Card className="border-0 panel-shadow"><CardHeader><CardTitle>Colaboradores inspecionados</CardTitle><CardDescription>Filtre os registos BPHF para consultar rapidamente o colaborador, o ponto avaliado e o resultado.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 md:grid-cols-2"><Select value={inspectionFilter} onValueChange={setInspectionFilter}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os colaboradores</SelectItem>{employees.data?.map((employee) => <SelectItem key={employee.id} value={String(employee.id)}>{employee.name}</SelectItem>)}</SelectContent></Select><Select value={resultFilter} onValueChange={setResultFilter}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os resultados</SelectItem><SelectItem value="C">Conforme (C)</SelectItem><SelectItem value="NC">Não conforme (NC)</SelectItem><SelectItem value="N/A">Não aplicável (N/A)</SelectItem></SelectContent></Select></div>{!factoryId ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Selecione a fábrica no cabeçalho para consultar os colaboradores inspecionados.</p> : inspections.isLoading ? <p className="text-sm text-muted-foreground">A carregar registos…</p> : inspections.data?.length ? <div className="divide-y overflow-hidden rounded-xl border border-slate-100">{inspections.data.map((inspection) => <div key={inspection.id} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium">{inspection.collaboratorName}</p><p className="mt-1 text-sm text-muted-foreground">{inspection.criterion} · {inspection.area}</p><p className="mt-1 text-xs text-muted-foreground">{new Date(inspection.completedAt).toLocaleString("pt-PT")}</p></div><Badge className={inspection.result === "NC" ? "bg-red-600 text-white hover:bg-red-600" : inspection.result === "C" ? "bg-emerald-100 text-emerald-800 hover:bg-emerald-100" : "bg-slate-100 text-slate-700 hover:bg-slate-100"}>{inspection.result}</Badge></div>)}</div> : <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Não existem registos com os filtros selecionados.</p>}</CardContent></Card>
    <Dialog open={employeeDialogOpen} onOpenChange={setEmployeeDialogOpen}><DialogContent><DialogHeader><DialogTitle>Adicionar colaborador inspecionado</DialogTitle><DialogDescription>O colaborador ficará disponível para todos os pontos de verificação BPHF.</DialogDescription></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Nome do colaborador</Label><Input value={newEmployeeName} onChange={(event) => setNewEmployeeName(event.target.value)} placeholder="Nome completo" /></div><Button className="w-full" disabled={!newEmployeeName.trim() || addEmployee.isPending} onClick={() => addEmployee.mutate({ name: newEmployeeName })}>{addEmployee.isPending ? "A adicionar…" : "Adicionar colaborador"}</Button></div></DialogContent></Dialog>
  </>;
}

type MetalProductCheck = { product: string; lot: string; result: "" | "C" | "NC"; notes: string; evidencePhotos: VerificationEvidencePhoto[] };
const newMetalProduct = (): MetalProductCheck => ({ product: "", lot: "", result: "", notes: "", evidencePhotos: [] });

function MetalDetectors({ createEntry, areas }: any) {
  const [area, setArea] = useState(""); const [products, setProducts] = useState<MetalProductCheck[]>([newMetalProduct()]);
  const areaSignature = areas.join("|");
  useEffect(() => setArea(""), [areaSignature]);
  const updateProduct = (index: number, updater: (product: MetalProductCheck) => MetalProductCheck) => setProducts((items) => items.map((item, itemIndex) => itemIndex === index ? updater(item) : item));
  async function submit(event: FormEvent) { event.preventDefault(); if (!area) return toast.error("Selecione a linha ou área antes de registar."); const incomplete = products.find((item) => !item.product.trim() || !item.result); if (incomplete) return toast.error("Identifique todos os produtos e escolha explicitamente C ou NC."); const invalid = products.find((item) => item.result === "NC" && !item.notes.trim()); if (invalid) return toast.error(`A observação é obrigatória para o produto ${invalid.product} com resultado NC.`); await Promise.all(products.map((item) => createEntry.mutateAsync({ module: "metal_detectors", title: `Detetor de metais — ${area} · ${item.product}`, area, result: item.result as "C" | "NC", notes: item.notes || undefined, payload: { product: item.product, lot: item.lot || null, productValidation: item.result, evidencePhotos: item.evidencePhotos }, createNonconformity: false, severity: "critical" }))); toast.success(`${products.length} produto${products.length === 1 ? "" : "s"} registado${products.length === 1 ? "" : "s"} na verificação de metais.`); setProducts([newMetalProduct()]); }
  const containsNc = products.some((item) => item.result === "NC");
  return <><ModuleHeader label="Verificação de detetores de metais" description="Registe os produtos testados por linha ou área, com conformidade individual." icon={Gauge} critical /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-900"><div className="flex gap-3"><AlertTriangle className="h-5 w-5 shrink-0 text-red-600" /><div><p className="font-semibold">Regra crítica ativa</p><p className="mt-1 text-red-800">Cada produto NC fica registado como incidência crítica. Se justificar uma Não Conformidade, crie-a no formulário próprio e associe a incidência.</p></div></div></div><div className="max-w-md space-y-2"><Label>Linha / área</Label><Select value={area} onValueChange={setArea} disabled={!areas.length}><SelectTrigger><SelectValue placeholder={areas.length ? "Selecione a linha" : "Selecione primeiro a fábrica ou linha"} /></SelectTrigger><SelectContent>{areas.map((item: string) => <SelectItem value={item} key={item}>{item}</SelectItem>)}</SelectContent></Select></div></CardContent></Card><Card className="border-0 panel-shadow"><CardHeader><div className="flex items-start justify-between gap-4"><div><CardTitle>Produtos verificados</CardTitle><CardDescription>Adicione todos os produtos testados. A conformidade e a observação são registadas de forma independente por produto.</CardDescription></div><Button type="button" size="sm" variant="outline" onClick={() => setProducts((items) => [...items, newMetalProduct()])}><Plus className="mr-1 h-3.5 w-3.5" />Produto</Button></div></CardHeader><CardContent className="space-y-4">{products.map((item, index) => <div key={index} className={`space-y-4 rounded-xl border p-4 ${item.result === "NC" ? "border-red-200 bg-red-50/40" : "border-slate-100"}`}><div className="flex items-center justify-between"><p className="font-mono-ui text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">Produto {index + 1}</p><Button type="button" size="icon" variant="ghost" className="h-7 w-7 text-slate-500 hover:text-red-700" disabled={products.length === 1} onClick={() => setProducts((items) => items.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="h-4 w-4" /></Button></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Produto</Label><Input required value={item.product} onChange={(event) => updateProduct(index, (current) => ({ ...current, product: event.target.value }))} placeholder="Produto testado" /></div><div className="space-y-2"><Label>Lote <span className="text-muted-foreground">(opcional)</span></Label><Input value={item.lot} onChange={(event) => updateProduct(index, (current) => ({ ...current, lot: event.target.value }))} placeholder="Lote do produto" /></div></div><div className="space-y-2"><Label>Conformidade do produto</Label><BinaryResultPicker value={item.result} onChange={(value) => updateProduct(index, (current) => ({ ...current, result: value }))} /></div><Notes value={item.notes} onChange={(value) => updateProduct(index, (current) => ({ ...current, notes: value }))} required={item.result === "NC"} />{item.result === "NC" && <NcEvidenceUploader module="metal_detectors" photos={item.evidencePhotos} onChange={(photos) => updateProduct(index, (current) => ({ ...current, evidencePhotos: photos }))} />}</div>)}</CardContent></Card><Button className="w-full" size="lg" variant={containsNc ? "destructive" : "default"} disabled={createEntry.isPending || !area}>{createEntry.isPending ? "A registar…" : containsNc ? "Registar incidência crítica por produto" : "Concluir verificação de produtos"}</Button></form></>;
}

function Sensory({ createEntry }: any) {
  const [product, setProduct] = useState(""); const [lot, setLot] = useState(""); const [validity, setValidity] = useState(""); const [notes, setNotes] = useState(""); const [scores, setScores] = useState({ aspeto: 3, fimDeBoca: 3, cor: 3, cheiro: 3, textura: 3, sabor: 3 }); const [evidencePhotos, setEvidencePhotos] = useState<VerificationEvidencePhoto[]>([]);
  const scoreInput = useMemo(() => scores, [scores]); const calculation = trpc.quality.calculateSensory.useQuery(scoreInput);
  function submit(event: FormEvent) { event.preventDefault(); const result = calculation.data && calculation.data.percentage >= 50 ? "C" : "NC"; createEntry.mutate({ module: "sensory", title: `Controlo sensorial${product ? ` — ${product}` : ""}`, area: "Controlo sensorial", result, notes, payload: { product, lot, validity, scores, calculation: calculation.data, weights: { Aspeto: "10%", "Fim de boca": "15%", Cor: "15%", Cheiro: "10%", Textura: "10%", Sabor: "40%" }, evidencePhotos }, createNonconformity: false, severity: "medium" }); }
  const isNc = Boolean(calculation.data && calculation.data.percentage < 50); return <><ModuleHeader label="Controlo sensorial de produto acabado" description="Avalie o produto acabado com os seis parâmetros e pesos fixos definidos." icon={FlaskConical} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="grid gap-4 p-6 md:grid-cols-3"><div className="space-y-2"><Label>Produto</Label><Input required value={product} onChange={(event) => setProduct(event.target.value)} placeholder="Produto acabado" /></div><div className="space-y-2"><Label>Lote</Label><Input required value={lot} onChange={(event) => setLot(event.target.value)} placeholder="Lote" /></div><div className="space-y-2"><Label>Validade</Label><Input required type="date" value={validity} onChange={(event) => setValidity(event.target.value)} /></div></CardContent></Card><div className="grid gap-4 md:grid-cols-2">{SENSORY_FIELDS.map((field) => <Card key={field.key} className="border-0 panel-shadow"><CardContent className="flex items-center justify-between p-5"><div><p className="font-medium">{field.label}</p><p className="font-mono-ui mt-1 text-xs text-teal-700">Peso fixo: {field.weight}</p></div><Select value={String(scores[field.key])} onValueChange={(value) => setScores((current) => ({ ...current, [field.key]: Number(value) }))}><SelectTrigger className="w-28"><SelectValue /></SelectTrigger><SelectContent>{[1, 2, 3, 4, 5].map((value) => <SelectItem value={String(value)} key={value}>{value} / 5</SelectItem>)}</SelectContent></Select></CardContent></Card>)}</div><Card className="border-0 panel-shadow"><CardContent className="grid gap-6 p-6 md:grid-cols-[1fr_auto]"><Notes value={notes} onChange={setNotes} required={isNc} /><div className="rounded-2xl bg-slate-900 px-7 py-5 text-center text-white"><p className="font-mono-ui text-xs uppercase tracking-[0.15em] text-teal-300">Resultado ponderado</p><p className="mt-2 font-mono-ui text-4xl font-semibold">{calculation.data?.percentage ?? 0}%</p><p className="mt-1 text-sm text-slate-300">{calculation.data?.scoreOnFive ?? 0} / 5</p><Badge className={isNc ? "mt-3 bg-red-500 text-white hover:bg-red-500" : "mt-3 bg-emerald-500 text-emerald-950 hover:bg-emerald-500"}>{isNc ? "Não conforme" : "Conforme"}</Badge></div></CardContent></Card>{isNc && <NcEvidenceUploader module="sensory" photos={evidencePhotos} onChange={setEvidencePhotos} />}<Button size="lg" className="w-full">Registar controlo sensorial</Button></form></>;
}

type DispatchLot = { lot: string; dispatchedQuantity: string };
type DispatchProductCheck = { name: string; orderedQuantity: number; lots: DispatchLot[]; productLabelResult: "" | "C" | "NC"; boxLabelResult: "" | "C" | "NC"; productTemperature: string; observations: string };
const newDispatchProduct = (name = "", orderedQuantity = 0): DispatchProductCheck => ({ name, orderedQuantity, lots: [{ lot: "", dispatchedQuantity: "" }], productLabelResult: "", boxLabelResult: "", productTemperature: "", observations: "" });

export function DispatchControl() {
  const utils = trpc.useUtils();
  const [profile, setProfile] = useState<"ambiente" | "congelado">("ambiente");
  const [orderNumber, setOrderNumber] = useState(""); const [customer, setCustomer] = useState(""); const [deliveryNote, setDeliveryNote] = useState("");
  const [vehicleTemperature, setVehicleTemperature] = useState(""); const [vehicleObservations, setVehicleObservations] = useState("");
  const [evidencePhotos, setEvidencePhotos] = useState<VerificationEvidencePhoto[]>([]);
  const [importedOrder, setImportedOrder] = useState<{ orderNumber: string; customer: string; products: Array<{ name: string; orderedQuantity: number }>; warnings: string[]; document: { name: string; url: string } } | null>(null);
  const [productChecks, setProductChecks] = useState<DispatchProductCheck[]>([newDispatchProduct()]);
  const [openProduct, setOpenProduct] = useState<number | null>(0);
  const profileDefinition = DISPATCH_CONTROL_CATALOG.profiles.find((item) => item.id === profile) ?? DISPATCH_CONTROL_CATALOG.profiles[0];
  const limit = profileDefinition.productTemperatureLimit;
  const updateProduct = (index: number, updater: (item: DispatchProductCheck) => DispatchProductCheck) => setProductChecks((items) => items.map((item, itemIndex) => itemIndex === index ? updater(item) : item));
  const productStatus = (item: DispatchProductCheck) => { const dispatched = item.lots.reduce((total, lot) => total + Number(lot.dispatchedQuantity || 0), 0); const complete = Boolean(item.name.trim() && item.lots.every((lot) => lot.lot.trim() && lot.dispatchedQuantity !== "") && item.productTemperature !== "" && item.productLabelResult && item.boxLabelResult); const result = complete && dispatched === item.orderedQuantity && item.productLabelResult === "C" && item.boxLabelResult === "C" && Number(item.productTemperature) <= limit ? "C" : "NC"; return { dispatched, complete, result }; };
  const allProductsComplete = productChecks.length > 0 && productChecks.every((item) => productStatus(item).complete);
  const vehicleResult = vehicleTemperature !== "" && Number(vehicleTemperature) <= limit ? "C" : "NC";
  const globalResult = allProductsComplete && vehicleTemperature !== "" && productChecks.every((item) => productStatus(item).result === "C") && vehicleResult === "C" ? "C" : "NC";
  const parseOrderPdf = trpc.quality.parseDispatchOrderPdf.useMutation({ onSuccess: (data) => { setImportedOrder(data); setOrderNumber(data.orderNumber); setCustomer(data.customer); setProductChecks(data.products.length ? data.products.map((item) => newDispatchProduct(item.name, item.orderedQuantity)) : [newDispatchProduct()]); setOpenProduct(data.products.length ? 0 : null); toast.success("Encomenda importada. Valide cada produto e respetivos lotes antes de concluir."); }, onError: (error) => toast.error(error.message) });
  const register = trpc.quality.registerDispatchControl.useMutation({ onSuccess: (data) => { utils.quality.dashboard.invalidate(); utils.quality.reports.invalidate(); utils.quality.listNcs.invalidate(); toast[data.conformity.result === "NC" ? "error" : "success"](data.conformity.result === "NC" ? "Expedição registada como incidência. Registe uma Não Conformidade no formulário próprio se necessário." : "Controlo à expedição registado como conforme."); setOrderNumber(""); setCustomer(""); setDeliveryNote(""); setVehicleTemperature(""); setVehicleObservations(""); setImportedOrder(null); setProductChecks([newDispatchProduct()]); setOpenProduct(0); }, onError: (error) => toast.error(error.message) });
  function submit(event: FormEvent) { event.preventDefault(); if (!allProductsComplete || vehicleTemperature === "") return toast.error("Preencha a validação obrigatória de todos os produtos, lotes, resultados e temperatura do carro."); const invalidProduct = productChecks.find((item) => productStatus(item).result === "NC" && !item.observations.trim()); if (invalidProduct) return toast.error(`Inclua observações no produto ${invalidProduct.name} quando a validação não está conforme.`); if (vehicleResult === "NC" && !vehicleObservations.trim()) return toast.error("Inclua uma observação geral quando a temperatura do carro não está conforme."); const first = productChecks[0]!; const firstStatus = productStatus(first); register.mutate({ profile, orderNumber, customer, deliveryNote: deliveryNote || undefined, product: first.name, lot: first.lots[0]!.lot, orderedBoxes: first.orderedQuantity, dispatchedBoxes: firstStatus.dispatched, productLabelResult: first.productLabelResult as "C" | "NC", boxLabelResult: first.boxLabelResult as "C" | "NC", productTemperature: Number(first.productTemperature), vehicleTemperature: Number(vehicleTemperature), observations: vehicleObservations || undefined, orderItems: importedOrder?.products ?? productChecks.map((item) => ({ name: item.name, orderedQuantity: item.orderedQuantity })), productChecks: productChecks.map((item) => ({ name: item.name, orderedQuantity: item.orderedQuantity, lots: item.lots.map((lot) => ({ lot: lot.lot, dispatchedQuantity: Number(lot.dispatchedQuantity) })), productLabelResult: item.productLabelResult as "C" | "NC", boxLabelResult: item.boxLabelResult as "C" | "NC", productTemperature: Number(item.productTemperature), observations: item.observations || undefined })), evidencePhotos, sourceOrderDocument: importedOrder?.document }); }
  async function importOrderPdf(file?: File) { if (!file) return; if (file.type !== "application/pdf") return toast.error("Selecione uma encomenda em formato PDF."); if (file.size > 12_000_000) return toast.error("A encomenda PDF deve ter no máximo 12 MB."); try { parseOrderPdf.mutate({ fileName: file.name, mimeType: "application/pdf", dataUrl: await fileAsDataUrl(file) }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler a encomenda PDF."); } }
  return <><ModuleHeader label="Controlo à expedição" description="Verificação diária única, comum a todas as fábricas e linhas. Pode registar controlos adicionais sempre que necessário." icon={Truck} commonToAllOperations /><form className="space-y-5" onSubmit={submit}>
    <Card className="border border-teal-100 bg-teal-50/60 shadow-sm"><CardContent className="space-y-4 p-5"><div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div><p className="font-medium text-teal-950">Importar encomenda PDF</p><p className="mt-1 text-sm text-teal-800">O sistema extrai o cliente, número da encomenda, produtos e quantidades pedidas. Confirme sempre os campos antes do registo.</p></div><div className="shrink-0"><Input aria-label="Carregar encomenda em PDF" type="file" accept="application/pdf" onChange={(event) => importOrderPdf(event.target.files?.[0])} disabled={parseOrderPdf.isPending} /></div></div>{parseOrderPdf.isPending && <p className="text-sm font-medium text-teal-800">A analisar a encomenda…</p>}{importedOrder && <div className="rounded-xl border border-teal-100 bg-white p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold text-slate-900">{importedOrder.document.name}</p><p className="mt-1 text-xs text-slate-600">Foram carregadas todas as linhas da encomenda para validação individual.</p></div><Button type="button" size="sm" variant="outline" onClick={() => { setImportedOrder(null); setProductChecks([newDispatchProduct()]); setOpenProduct(0); }}>Remover importação</Button></div>{importedOrder.products.length ? <div className="mt-3 divide-y overflow-hidden rounded-xl border border-slate-100">{importedOrder.products.map((item, index) => <div key={`${item.name}-${index}`} className="flex items-center justify-between gap-3 px-3 py-2 text-sm"><span>{item.name}</span><span className="font-mono-ui font-semibold text-teal-800">{item.orderedQuantity} cx</span></div>)}</div> : <p className="mt-3 text-sm text-amber-800">Não foram identificadas linhas de produto. Preencha os produtos manualmente.</p>}{importedOrder.warnings.length ? <ul className="mt-3 list-disc space-y-1 pl-5 text-xs text-amber-800">{importedOrder.warnings.map((warning) => <li key={warning}>{warning}</li>)}</ul> : null}</div>}</CardContent></Card>
    <Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="flex flex-col gap-4 rounded-2xl border border-slate-100 bg-slate-50 p-4 md:flex-row md:items-center md:justify-between"><div><p className="font-medium text-slate-950">Perfil de validação</p><p className="mt-1 text-sm text-slate-600">Valide cada produto antes do fecho da expedição.</p></div><Select value={profile} onValueChange={(value) => setProfile(value as "ambiente" | "congelado")}><SelectTrigger className="w-full md:w-80"><SelectValue /></SelectTrigger><SelectContent>{DISPATCH_CONTROL_CATALOG.profiles.map((item) => <SelectItem key={item.id} value={item.id}>{item.label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>N.º Encomenda</Label><Input required value={orderNumber} onChange={(event) => setOrderNumber(event.target.value)} /></div><div className="space-y-2"><Label>Cliente</Label><Input required value={customer} onChange={(event) => setCustomer(event.target.value)} /></div><div className="space-y-2"><Label>N.º Guia <span className="text-muted-foreground">(opcional)</span></Label><Input value={deliveryNote} onChange={(event) => setDeliveryNote(event.target.value)} /></div></div></CardContent></Card>
    <Card className="border-0 panel-shadow"><CardHeader><div className="flex items-start justify-between gap-4"><div><CardTitle>Produtos da encomenda</CardTitle><CardDescription>Todos os produtos importados são listados. Abra cada linha para validar lotes, quantidades, rotulagem e temperatura.</CardDescription></div><Button type="button" size="sm" variant="outline" onClick={() => { setProductChecks((items) => [...items, newDispatchProduct()]); setOpenProduct(productChecks.length); }}><Plus className="mr-1 h-3.5 w-3.5" />Adicionar produto</Button></div></CardHeader><CardContent className="space-y-3">{productChecks.map((item, index) => { const status = productStatus(item); const isOpen = openProduct === index; return <div key={index} className={`overflow-hidden rounded-xl border ${status.complete && status.result === "NC" ? "border-red-200" : "border-slate-100"}`}><button type="button" className="flex w-full items-center justify-between gap-4 p-4 text-left hover:bg-slate-50" onClick={() => setOpenProduct(isOpen ? null : index)}><div><p className="font-medium">{item.name || `Produto ${index + 1}`}</p><p className="mt-1 text-sm text-muted-foreground">{item.orderedQuantity} cx pedidas · {status.dispatched} cx registadas por lote</p></div><div className="flex items-center gap-3">{status.complete && <Badge className={status.result === "C" ? "bg-emerald-100 text-emerald-800 hover:bg-emerald-100" : "bg-red-600 text-white hover:bg-red-600"}>{status.result}</Badge>}{isOpen ? <ChevronUp className="h-5 w-5 text-slate-500" /> : <ChevronDown className="h-5 w-5 text-slate-500" />}</div></button>{isOpen && <div className="space-y-5 border-t border-slate-100 p-4"><div className="grid gap-4 md:grid-cols-[1fr_10rem]"><div className="space-y-2"><Label>Produto</Label><Input required value={item.name} onChange={(event) => updateProduct(index, (current) => ({ ...current, name: event.target.value }))} /></div><div className="space-y-2"><Label>Qtd. pedida</Label><Input required min="0" type="number" value={item.orderedQuantity} onChange={(event) => updateProduct(index, (current) => ({ ...current, orderedQuantity: Number(event.target.value) }))} /></div></div><div className="space-y-3"><div className="flex items-center justify-between"><Label>Quantidade expedida por lote <span className="text-red-600">(obrigatória)</span></Label><Button type="button" size="sm" variant="outline" onClick={() => updateProduct(index, (current) => ({ ...current, lots: [...current.lots, { lot: "", dispatchedQuantity: "" }] }))}><Plus className="mr-1 h-3.5 w-3.5" />Lote</Button></div>{item.lots.map((lot, lotIndex) => <div key={lotIndex} className="grid gap-3 rounded-xl bg-slate-50 p-3 sm:grid-cols-[1fr_11rem_auto]"><div className="space-y-1"><Label className="text-xs">Lote</Label><Input required value={lot.lot} onChange={(event) => updateProduct(index, (current) => ({ ...current, lots: current.lots.map((currentLot, currentIndex) => currentIndex === lotIndex ? { ...currentLot, lot: event.target.value } : currentLot) }))} placeholder="N.º do lote" /></div><div className="space-y-1"><Label className="text-xs">Qtd. expedida</Label><Input required min="0" type="number" value={lot.dispatchedQuantity} onChange={(event) => updateProduct(index, (current) => ({ ...current, lots: current.lots.map((currentLot, currentIndex) => currentIndex === lotIndex ? { ...currentLot, dispatchedQuantity: event.target.value } : currentLot) }))} /></div><Button type="button" size="icon" variant="ghost" className="self-end text-slate-500 hover:text-red-700" disabled={item.lots.length === 1} onClick={() => updateProduct(index, (current) => ({ ...current, lots: current.lots.filter((_, currentIndex) => currentIndex !== lotIndex) }))}><Trash2 className="h-4 w-4" /></Button></div>)}</div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Rotulagem do produto</Label><BinaryResultPicker value={item.productLabelResult} onChange={(value) => updateProduct(index, (current) => ({ ...current, productLabelResult: value }))} /></div><div className="space-y-2"><Label>Rotulagem da caixa</Label><BinaryResultPicker value={item.boxLabelResult} onChange={(value) => updateProduct(index, (current) => ({ ...current, boxLabelResult: value }))} /></div><div className="space-y-2"><div className="flex items-center gap-1.5"><Label>Temp. produto (°C)</Label><ContextualHelpIcon label="Ajuda sobre a temperatura do produto">A temperatura do produto deve ser igual ou inferior a {limit} °C.</ContextualHelpIcon></div><Input required type="number" step="0.1" value={item.productTemperature} onChange={(event) => updateProduct(index, (current) => ({ ...current, productTemperature: event.target.value }))} placeholder={`Máximo ${limit} °C`} /></div></div><Notes value={item.observations} onChange={(value) => updateProduct(index, (current) => ({ ...current, observations: value }))} required={status.complete && status.result === "NC"} /></div>}</div>; })}</CardContent></Card>
    <Card className="border-0 panel-shadow"><CardHeader><CardTitle>Fecho da expedição</CardTitle><CardDescription>Registe a temperatura do carro e confirme a conformidade geral após validar todos os produtos.</CardDescription></CardHeader><CardContent className="space-y-5"><div className="grid gap-4 md:grid-cols-[1fr_0.8fr]"><div className="space-y-2 rounded-xl border border-slate-100 p-4"><div className="flex items-center gap-1.5"><Label>Temp. do carro (°C)</Label><ContextualHelpIcon label="Ajuda sobre a temperatura do carro">A temperatura do compartimento de transporte deve ser igual ou inferior a {limit} °C.</ContextualHelpIcon></div><Input required type="number" step="0.1" value={vehicleTemperature} onChange={(event) => setVehicleTemperature(event.target.value)} placeholder={`Máximo ${limit} °C`} /></div><div className={`rounded-xl border p-4 ${globalResult === "C" ? "border-emerald-100 bg-emerald-50" : "border-red-100 bg-red-50"}`}><p className="font-mono-ui text-xs uppercase tracking-[0.12em]">Conformidade geral</p><p className="mt-1 text-2xl font-semibold">{allProductsComplete && vehicleTemperature !== "" ? (globalResult === "C" ? "Conforme" : "Não conforme") : "A aguardar validações"}</p><p className="mt-1 text-sm opacity-80">Produtos e temperatura do carro são avaliados no fecho.</p></div></div><Notes value={vehicleObservations} onChange={setVehicleObservations} required={vehicleTemperature !== "" && vehicleResult === "NC"} />{globalResult === "NC" && <NcEvidenceUploader module="dispatch_control" photos={evidencePhotos} onChange={setEvidencePhotos} />}<div className="rounded-xl border border-teal-100 bg-teal-50/60 p-4 text-sm text-teal-900"><p className="font-medium">Registos adicionais</p><p className="mt-1 text-teal-800">A primeira expedição do dia conclui a verificação diária obrigatória. Pode submeter mais expedições neste mesmo formulário sem criar novas pendências.</p></div><Button className="w-full" size="lg" variant={globalResult === "NC" ? "destructive" : "default"} disabled={register.isPending || !allProductsComplete || vehicleTemperature === ""}>{register.isPending ? "A registar…" : globalResult === "NC" ? "Registar incidência à expedição" : "Registar controlo à expedição"}</Button></CardContent></Card>
  </form></>;
}

export function ShelfLife({ createEntry }: any) {
  const [result, setResult] = useState<"" | "C" | "NC">("");
  const [product, setProduct] = useState("");
  const [lot, setLot] = useState("");
  const [validity, setValidity] = useState("");
  const [reason, setReason] = useState("");
  const [evidencePhotos, setEvidencePhotos] = useState<VerificationEvidencePhoto[]>([]);
  const isNcComplete = Boolean(product.trim() && lot.trim() && validity && reason.trim());

  function submit(event: FormEvent) {
    event.preventDefault();
    if (!result) return toast.error("Escolha explicitamente C ou NC antes de registar.");
    if (result === "NC" && !isNcComplete) return toast.error("Em caso de NC, identifique o produto, lote, validade e motivo da incidência.");
    createEntry.mutate({
      module: "shelf_life",
      title: result === "NC" ? `Incidência shelf-life — ${product}` : "Shelf-life — Conforme",
      area: "Shelf-life",
      result: result as "C" | "NC",
      notes: result === "NC" ? reason : undefined,
      payload: {
        observationResult: result,
        product: result === "NC" ? product : null,
        lot: result === "NC" ? lot : null,
        validity: result === "NC" ? validity : null,
        reason: result === "NC" ? reason : null,
        dailyIncidenceGenerated: result === "NC",
        evidencePhotos,
      },
      createNonconformity: false,
      severity: "medium",
    });
  }

  return <><ModuleHeader label="Controlo de amostras em shelf-life" description="Registe a verificação diária como C ou NC. Os dados de rastreabilidade surgem apenas quando existe uma incidência." icon={PackageSearch} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="rounded-xl border border-teal-100 bg-teal-50/70 p-4"><p className="font-medium text-teal-950">Verificação diária da amostra</p><p className="mt-1 text-sm text-teal-800">Registe primeiro o resultado. Um NC cria uma incidência diária que pode, se necessário, ser associada posteriormente a uma Não Conformidade.</p></div><div className="space-y-2"><div className="flex items-center gap-1.5"><Label>Resultado da verificação global:</Label><ContextualHelpIcon label="Explicação do resultado da verificação global">Selecione C quando a amostra estiver conforme. Escolha NC quando existir um desvio; serão pedidos os dados de rastreabilidade e criada uma incidência diária.</ContextualHelpIcon></div><BinaryResultPicker value={result} onChange={setResult} showHelp={false} /></div>{result === "NC" && <div className="space-y-5 rounded-2xl border border-red-200 bg-red-50/60 p-5"><div><p className="font-semibold text-red-950">Detalhe da incidência</p><p className="mt-1 text-sm text-red-800">Estes dados são obrigatórios para garantir a rastreabilidade da incidência.</p></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label htmlFor="shelf-life-product">Produto</Label><Input id="shelf-life-product" required value={product} onChange={(event) => setProduct(event.target.value)} placeholder="Produto da amostra" /></div><div className="space-y-2"><Label htmlFor="shelf-life-lot">Lote</Label><Input id="shelf-life-lot" required value={lot} onChange={(event) => setLot(event.target.value)} placeholder="Lote" /></div><div className="space-y-2"><Label htmlFor="shelf-life-validity">Validade</Label><Input id="shelf-life-validity" required type="date" value={validity} onChange={(event) => setValidity(event.target.value)} /></div></div><div className="space-y-2"><Label htmlFor="shelf-life-reason">Motivo / observações da incidência</Label><Textarea id="shelf-life-reason" required value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Descreva o desvio observado na amostra." /></div><NcEvidenceUploader module="shelf_life" photos={evidencePhotos} onChange={setEvidencePhotos} /></div>}<Button size="lg" className="w-full" variant={result === "NC" ? "destructive" : "default"} disabled={createEntry.isPending || !result || (result === "NC" && !isNcComplete)}>{result === "NC" ? "Registar incidência" : result === "C" ? "Registar verificação conforme" : "Selecione o resultado"}</Button></CardContent></Card></form></>;
}

function MonthlyChecklistLegacy({ createEntry }: any) {
  const { factories, factoryId, setFactoryId } = useControlFactory(); const { canManage } = useQualityAccess();
  const monthlyFactories = factories.filter((factory) => [1, 2, 3].includes(factory.id));
  const items = trpc.quality.listChecklistItems.useQuery(factoryId ? { factoryId: Number(factoryId) } : undefined); const monthlyProgress = trpc.quality.monthlyChecklistProgress.useQuery(); const initialize = trpc.quality.initializeChecklist.useMutation({ onSuccess: () => { items.refetch(); toast.success("Itens iniciais de checklist configurados."); }, onError: (error) => toast.error(error.message) }); const addItem = trpc.quality.addChecklistItem.useMutation({ onSuccess: () => { items.refetch(); setNewLabel(""); setNewFactoryIds([]); toast.success("Ponto de controlo adicionado."); }, onError: (error) => toast.error(error.message) }); const updateItem = trpc.quality.updateChecklistItem.useMutation({ onSuccess: () => { items.refetch(); setEditingItem(null); setNewLabel(""); setNewFactoryIds([]); toast.success("Ponto de controlo atualizado."); }, onError: (error) => toast.error(error.message) }); const removeItem = trpc.quality.removeChecklistItem.useMutation({ onSuccess: () => { items.refetch(); toast.success("Ponto de controlo removido."); }, onError: (error) => toast.error(error.message) }); const [area, setArea] = useState(""); const [results, setResults] = useState<Record<number, Result>>({}); const [notes, setNotes] = useState<Record<number, string>>({}); const [manageOpen, setManageOpen] = useState(false); const [newArea, setNewArea] = useState(""); const [newLabel, setNewLabel] = useState(""); const [newFactoryIds, setNewFactoryIds] = useState<number[]>([]); const [editingItem, setEditingItem] = useState<any>(null);
  useEffect(() => { if (monthlyFactories.length && !monthlyFactories.some((factory) => String(factory.id) === factoryId)) setFactoryId(String(monthlyFactories[0].id)); }, [factoryId, monthlyFactories, setFactoryId]);
  const availableAreas = Array.from(new Set(items.data?.map((item) => item.area).filter((value) => value !== "Geral") ?? []));
  useEffect(() => { if (availableAreas.length && !availableAreas.includes(area)) setArea(availableAreas[0]); }, [area, availableAreas]);
  const grouped = items.data?.filter((item) => item.area === area) ?? [];
  const applicable = grouped.filter((item) => (results[item.id] ?? "C") !== "N/A");
  const conformity = applicable.length ? Math.round((applicable.filter((item) => (results[item.id] ?? "C") === "C").length / applicable.length) * 100) : 0;
  async function submit(event: FormEvent) { event.preventDefault(); if (grouped.some((item) => (results[item.id] ?? "C") === "NC" && !notes[item.id]?.trim())) return toast.error("Inclua observações em todos os itens NC."); await Promise.all(grouped.map((item) => { const result = results[item.id] ?? "C"; return createEntry.mutateAsync({ module: "monthly_checklist", title: item.label, area, result, notes: notes[item.id] || undefined, payload: { checklistItemId: item.id }, createNonconformity: result === "NC", severity: "medium" }); })); toast.success("Checklist mensal registada."); }
  return <><ModuleHeader label="Checklist mensal" description="Avalie os pontos por zona e acompanhe o preenchimento do mês nas três fábricas." icon={ClipboardCheck} hideProgress /><Card className="border-0 panel-shadow"><CardHeader><div className="flex items-start justify-between gap-3"><div><CardTitle>Preenchimento do mês</CardTitle><CardDescription>Acompanhe a conclusão do checklist mensal por fábrica.</CardDescription></div>{canManage && <Button size="sm" variant="outline" onClick={() => setManageOpen(true)}><Pencil className="mr-1 h-3.5 w-3.5" />Gerir pontos</Button>}</div></CardHeader><CardContent className="grid gap-3 md:grid-cols-3">{monthlyFactories.map((factory) => { const progress = monthlyProgress.data?.find((item) => item.factoryId === factory.id); return <div key={factory.id} className="rounded-xl border border-slate-100 p-4"><div className="flex items-center justify-between gap-3"><p className="text-sm font-medium">{factory.name}</p><span className="font-mono-ui text-sm text-teal-700">{progress?.percentage ?? 0}%</span></div><Progress value={progress?.percentage ?? 0} className="mt-3 h-2" /><p className="mt-2 text-xs text-muted-foreground">{progress?.completed ?? 0} de {progress?.total ?? 0} pontos concluídos</p></div>; })}</CardContent></Card><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div className="w-full max-w-md space-y-2"><Label>Zona</Label><Select value={area} onValueChange={setArea}><SelectTrigger><SelectValue placeholder="Selecione a zona" /></SelectTrigger><SelectContent>{availableAreas.map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="w-full max-w-xs"><div className="mb-2 flex justify-between text-sm"><span>Taxa conformidade</span><span className="font-mono-ui font-semibold">{conformity}%</span></div><Progress value={conformity} /></div></CardContent></Card>{!items.isLoading && !items.data?.length && <Button type="button" variant="outline" onClick={() => initialize.mutate()} disabled={initialize.isPending}>{initialize.isPending ? "A configurar…" : "Carregar pontos iniciais"}</Button>}{grouped.map((item, index) => { const result = results[item.id] ?? "C"; return <Card key={item.id} className="border-0 panel-shadow"><CardContent className="space-y-4 p-5"><div className="flex items-center justify-between gap-3"><div className="flex gap-3"><span className="font-mono-ui rounded-lg bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{String(index + 1).padStart(2, "0")}</span><p className="font-medium">{item.label}</p></div>{canManage && <Button type="button" size="icon" variant="ghost" className="text-slate-500 hover:text-red-700" onClick={() => removeItem.mutate({ id: item.id })}><Trash2 className="h-4 w-4" /></Button>}</div><ResultPicker value={result} onChange={(value) => setResults((current) => ({ ...current, [item.id]: value }))} /><Notes value={notes[item.id] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [item.id]: value }))} required={result === "NC"} /></CardContent></Card>; })}{grouped.length > 0 && <Button className="w-full" size="lg" disabled={createEntry.isPending}>Concluir checklist mensal</Button>}</form><Dialog open={manageOpen} onOpenChange={setManageOpen}><DialogContent><DialogHeader><DialogTitle>Gerir pontos de controlo</DialogTitle><DialogDescription>Adicione pontos às fábricas escolhidas ou remova pontos diretamente da lista mensal.</DialogDescription></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Zona</Label><Input value={newArea} onChange={(event) => setNewArea(event.target.value)} placeholder="Ex.: Produção" /></div><div className="space-y-2"><Label>Novo ponto</Label><Input value={newLabel} onChange={(event) => setNewLabel(event.target.value)} placeholder="Descrição do ponto de controlo" /></div><div className="space-y-2"><Label>Fábricas atribuídas</Label><div className="flex flex-wrap gap-2">{monthlyFactories.map((factory) => <Button key={factory.id} type="button" size="sm" variant={factoryId === String(factory.id) ? "default" : "outline"} onClick={() => setFactoryId(String(factory.id))}>{factory.name}</Button>)}</div></div><Button className="w-full" disabled={!factoryId || !newLabel.trim() || !newArea.trim() || addItem.isPending} onClick={() => addItem.mutate({ factoryIds: [Number(factoryId)], area: newArea, label: newLabel })}><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></div></DialogContent></Dialog></>;
}

function MonthlyChecklistV2({ createEntry }: any) {
  const { factories, factoryId, setFactoryId } = useControlFactory();
  const { canManage } = useQualityAccess();
  const monthlyFactories = factories.filter((factory) => [1, 2, 3].includes(factory.id));
  const items = trpc.quality.listChecklistItems.useQuery(factoryId ? { factoryId: Number(factoryId) } : undefined);
  const monthlyProgress = trpc.quality.monthlyChecklistProgress.useQuery();
  const utils = trpc.useUtils();
  const [area, setArea] = useState("");
  const [results, setResults] = useState<Record<number, Result | "">>({});
  const [notes, setNotes] = useState<Record<number, string>>({});
  const [evidenceByItem, setEvidenceByItem] = useState<Record<number, VerificationEvidencePhoto[]>>({});
  const [manageOpen, setManageOpen] = useState(false);
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any>(null);
  const [pointArea, setPointArea] = useState("");
  const [pointLabel, setPointLabel] = useState("");
  const [pointFactoryIds, setPointFactoryIds] = useState<number[]>([]);

  const refresh = () => { items.refetch(); monthlyProgress.refetch(); utils.quality.listChecklistItems.invalidate(); };
  const addItem = trpc.quality.addChecklistItem.useMutation({ onSuccess: () => { refresh(); setEditorOpen(false); toast.success("Ponto de controlo adicionado."); }, onError: (error) => toast.error(error.message) });
  const updateItem = trpc.quality.updateChecklistItem.useMutation({ onSuccess: () => { refresh(); setEditorOpen(false); toast.success("Ponto de controlo atualizado."); }, onError: (error) => toast.error(error.message) });
  const removeItem = trpc.quality.removeChecklistItem.useMutation({ onSuccess: () => { refresh(); toast.success("Ponto de controlo removido."); }, onError: (error) => toast.error(error.message) });

  useEffect(() => { if (monthlyFactories.length && !monthlyFactories.some((factory) => String(factory.id) === factoryId)) setFactoryId(String(monthlyFactories[0].id)); }, [factoryId, monthlyFactories, setFactoryId]);
  const areas = Array.from(new Set((items.data ?? []).map((item) => item.area)));
  useEffect(() => { if (areas.length && !areas.includes(area)) setArea(areas[0]); }, [area, areas]);
  const grouped = (items.data ?? []).filter((item) => item.area === area);
  const applicable = grouped.filter((item) => results[item.id] && results[item.id] !== "N/A");
  const conformity = applicable.length ? Math.round((applicable.filter((item) => results[item.id] === "C").length / applicable.length) * 100) : 0;

  const openCreate = () => { setManageOpen(false); setEditingItem(null); setPointArea(areas[0] ?? "Geral"); setPointLabel(""); setPointFactoryIds(factoryId ? [Number(factoryId)] : []); setEditorOpen(true); };
  const openEdit = (item: any) => { setManageOpen(false); setEditingItem(item); setPointArea(item.area); setPointLabel(item.label); setPointFactoryIds(item.factoryIds ?? []); setEditorOpen(true); };
  const toggleFactory = (id: number) => setPointFactoryIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const savePoint = () => { if (!pointArea.trim() || !pointLabel.trim() || !pointFactoryIds.length) return toast.error("Indique a zona, o ponto e pelo menos uma fábrica."); const input = { factoryIds: pointFactoryIds, area: pointArea.trim(), label: pointLabel.trim() }; if (editingItem) updateItem.mutate({ id: editingItem.id, ...input }); else addItem.mutate(input); };
  async function submit(event: FormEvent) { event.preventDefault(); if (grouped.some((item) => !results[item.id])) return toast.error("Escolha explicitamente C, NC ou N/A em todos os pontos antes de concluir."); if (grouped.some((item) => results[item.id] === "NC" && !notes[item.id]?.trim())) return toast.error("Inclua observações em todos os pontos NC."); await Promise.all(grouped.map((item) => { const result = results[item.id] as Result; return createEntry.mutateAsync({ module: "monthly_checklist", title: item.label, area, result, notes: notes[item.id] || undefined, payload: { checklistItemId: item.id, evidencePhotos: evidenceByItem[item.id] ?? [] }, createNonconformity: false, severity: "medium" }); })); refresh(); toast.success("Checklist mensal registado."); }

  return <>
    <ModuleHeader label="Checklist mensal" description="Avalie os pontos por zona e acompanhe o preenchimento do mês nas três fábricas." icon={ClipboardCheck} hideProgress><div className="mt-5 rounded-xl border border-slate-700 bg-slate-800/70 p-4"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-sm font-medium text-white">Preenchimento do mês</p><p className="mt-1 text-xs text-slate-300">Acompanhe a conclusão do checklist mensal nas três fábricas.</p></div>{canManage && <div className="flex flex-wrap gap-2"><Button size="sm" variant="secondary" className="bg-slate-700 text-white hover:bg-slate-600" onClick={() => setManageOpen(true)}><SlidersHorizontal className="mr-2 h-4 w-4" />Gerir pontos</Button><Button size="sm" className="bg-teal-600 text-white hover:bg-teal-500" onClick={openCreate}><Plus className="mr-2 h-4 w-4" />Novo ponto</Button></div>}</div><div className="mt-4 grid gap-3 md:grid-cols-3">{monthlyFactories.map((factory) => { const progress = monthlyProgress.data?.find((item) => item.factoryId === factory.id); return <div key={factory.id} className="rounded-xl border border-slate-700 bg-slate-900/50 p-3"><div className="flex items-center justify-between gap-3"><p className="text-sm font-medium text-white">{factory.name}</p><span className="font-mono-ui text-sm text-teal-300">{progress?.percentage ?? 0}%</span></div><Progress value={progress?.percentage ?? 0} className="mt-3 h-2" /><p className="mt-2 text-xs text-slate-300">{progress?.completed ?? 0} de {progress?.total ?? 0} pontos concluídos</p></div>; })}</div></div></ModuleHeader>
    <form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div className="w-full max-w-md space-y-2"><Label>Zona</Label><Select value={area} onValueChange={setArea}><SelectTrigger><SelectValue placeholder="Selecione a zona" /></SelectTrigger><SelectContent>{areas.map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="w-full max-w-xs"><div className="mb-2 flex justify-between text-sm"><span>Taxa conformidade</span><span className="font-mono-ui font-semibold">{conformity}%</span></div><Progress value={conformity} /><p className="mt-1 text-xs text-muted-foreground">Os pontos N/A não entram no cálculo.</p></div></CardContent></Card>{grouped.map((item, index) => { const result = results[item.id] ?? ""; return <Card key={item.id} className="border-0 panel-shadow"><CardContent className="space-y-4 p-5"><div className="flex items-center justify-between gap-3"><div className="flex gap-3"><span className="font-mono-ui rounded-lg bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{String(index + 1).padStart(2, "0")}</span><p className="font-medium">{item.label}</p></div>{canManage && <div className="flex gap-1"><Button type="button" size="icon" variant="ghost" className="text-slate-500 hover:text-teal-700" onClick={() => openEdit(item)}><Pencil className="h-4 w-4" /></Button><Button type="button" size="icon" variant="ghost" className="text-slate-500 hover:text-red-700" onClick={() => removeItem.mutate({ id: item.id })}><Trash2 className="h-4 w-4" /></Button></div>}</div><ResultPicker value={result} onChange={(value) => setResults((current) => ({ ...current, [item.id]: value }))} /><Notes value={notes[item.id] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [item.id]: value }))} required={result === "NC"} />{result === "NC" && <NcEvidenceUploader module="monthly_checklist" photos={evidenceByItem[item.id] ?? []} onChange={(photos) => setEvidenceByItem((current) => ({ ...current, [item.id]: photos }))} />}</CardContent></Card>; })}{grouped.length > 0 && <Button className="w-full" size="lg" disabled={createEntry.isPending || grouped.some((item) => !results[item.id])}>Concluir checklist mensal</Button>}</form>
    <Dialog open={manageOpen} onOpenChange={setManageOpen}><DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-3xl"><DialogHeader><DialogTitle>Gerir pontos de controlo</DialogTitle><DialogDescription>Consulte e mantenha os pontos da fábrica selecionada, sem sair da Checklist mensal.</DialogDescription></DialogHeader><div className="flex justify-end"><Button onClick={openCreate}><Plus className="mr-2 h-4 w-4" />Novo ponto</Button></div><div className="divide-y rounded-xl border border-slate-100">{items.isLoading ? <p className="p-4 text-sm text-muted-foreground">A carregar pontos de controlo…</p> : (items.data ?? []).map((item) => <div key={item.id} className="flex items-center gap-3 p-4"><div className="min-w-0 flex-1"><p className="font-medium">{item.label}</p><p className="mt-1 text-sm text-muted-foreground">{item.area} · {(item.factoryIds ?? []).map((id) => monthlyFactories.find((factory) => factory.id === id)?.name).filter(Boolean).join(", ")}</p></div><div className="flex gap-1"><Button size="icon" variant="outline" aria-label={`Editar ${item.label}`} onClick={() => openEdit(item)}><Pencil className="h-4 w-4" /></Button><Button size="icon" variant="outline" className="border-red-200 text-red-700 hover:bg-red-50 hover:text-red-800" aria-label={`Eliminar ${item.label}`} onClick={() => removeItem.mutate({ id: item.id })}><Trash2 className="h-4 w-4" /></Button></div></div>)}{!items.isLoading && !(items.data ?? []).length && <p className="p-4 text-sm text-muted-foreground">Não existem pontos configurados para esta fábrica.</p>}</div></DialogContent></Dialog>
    <Dialog open={editorOpen} onOpenChange={setEditorOpen}><DialogContent><DialogHeader><DialogTitle>{editingItem ? "Editar ponto de controlo" : "Novo ponto de controlo"}</DialogTitle><DialogDescription>Defina a zona, o ponto e as fábricas onde deve ser verificado.</DialogDescription></DialogHeader><div className="space-y-4"><div className="space-y-2"><Label>Zona</Label><Input value={pointArea} onChange={(event) => setPointArea(event.target.value)} placeholder="Ex.: Produção" /></div><div className="space-y-2"><Label>Ponto de controlo</Label><Input value={pointLabel} onChange={(event) => setPointLabel(event.target.value)} /></div><div className="space-y-2"><Label>Fábricas atribuídas</Label><div className="grid gap-2 sm:grid-cols-3">{monthlyFactories.map((factory) => <Button key={factory.id} type="button" variant={pointFactoryIds.includes(factory.id) ? "default" : "outline"} className="justify-start" onClick={() => toggleFactory(factory.id)}>{factory.name}</Button>)}</div></div><Button className="w-full" disabled={addItem.isPending || updateItem.isPending} onClick={savePoint}>{editingItem ? "Guardar alterações" : "Adicionar ponto"}</Button></div></DialogContent></Dialog>
  </>;
}

const ALLERGEN_ANALYSIS_CATEGORIES = [
  { label: "Glúten", tests: ["Análise ao glúten superfícies", "Glúten fardamento", "Teste rápido ao glúten Matérias-primas", "Teste rápido glúten Produto acabado", "Teste Elisa glúten MP", "Teste Elisa Glúten Produto acabado"] },
  { label: "Soja", tests: ["Teste rápido soja"] },
  { label: "Leite", tests: ["Teste rápido leite"] },
  { label: "Sésamo", tests: ["Teste rápido sementes de sésamo"] },
  { label: "Frutos de Casca Rija", tests: ["Teste rápido nozes", "Teste rápido amêndoas", "Teste rápido avelãs"] },
  { label: "Tremoço", tests: ["Teste Elisa Tremoço"] },
] as const;

type AnalysisResult = "negative" | "positive" | "conform" | "nonconform";
const ANALYSIS_RESULTS: Array<{ value: AnalysisResult; label: string; controlResult: "C" | "NC" }> = [
  { value: "negative", label: "Negativo", controlResult: "C" },
  { value: "positive", label: "Positivo", controlResult: "NC" },
  { value: "conform", label: "Conforme", controlResult: "C" },
  { value: "nonconform", label: "Não Conforme", controlResult: "NC" },
];

export function InternalAnalysis({ createEntry }: any) {
  const { activeProfile } = useQualityAccess();
  const [tests, setTests] = useState<string[]>([]);
  const [samples, setSamples] = useState<Array<{ product: string; client: string; lot: string; result: AnalysisResult | ""; ppm: string }>>([{ product: "", client: "", lot: "", result: "", ppm: "" }]);
  const [notes, setNotes] = useState("");
  const [photos, setPhotos] = useState<Array<{ url: string; fileName: string; mimeType: "image/jpeg" | "image/png" | "image/webp" }>>([]);
  const utils = trpc.useUtils();
  const uploadPhoto = trpc.quality.uploadInternalAnalysisPhoto.useMutation({ onError: (error) => toast.error(error.message) });
  const selectedAnalyses = tests.reduce<Array<{ test: string; category: string }>>((selected, test) => {
    const category = ALLERGEN_ANALYSIS_CATEGORIES.find((item) => item.tests.some((analysis) => analysis === test));
    if (category) selected.push({ test, category: String(category.label) });
    return selected;
  }, []);
  const selectedCategories = Array.from(new Set(selectedAnalyses.map((item) => item.category)));
  const isElisa = selectedAnalyses.some((item) => item.test.toLocaleLowerCase("pt-PT").includes("elisa"));
  const toggleTest = (test: string) => setTests((current) => current.includes(test) ? current.filter((item) => item !== test) : [...current, test]);
  const updateSample = (index: number, update: (sample: typeof samples[number]) => typeof samples[number]) => setSamples((current) => current.map((sample, sampleIndex) => sampleIndex === index ? update(sample) : sample));
  const addSample = () => setSamples((current) => [...current, { product: "", client: "", lot: "", result: "", ppm: "" }]);
  const isLimitOfQuantification = (value: string) => value.trim().toLocaleUpperCase("pt-PT") === "<L.Q.";
  const validElisaResult = (value: string) => isLimitOfQuantification(value) || (value.trim() !== "" && Number.isFinite(Number(value)) && Number(value) >= 0);

  async function addPhoto(file?: File) {
    if (!file) return;
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return toast.error("Use uma fotografia JPG, PNG ou WEBP.");
    if (file.size > 4_500_000) return toast.error("Cada fotografia deve ter no máximo 4,5 MB.");
    if (photos.length >= 5) return toast.error("Pode anexar até cinco fotografias por análise.");
    try {
      const dataUrl = await fileAsDataUrl(file);
      uploadPhoto.mutate({ fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataUrl }, { onSuccess: (photo) => setPhotos((current) => [...current, photo]) });
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível ler a fotografia."); }
  }

  function submit(event: FormEvent) {
    event.preventDefault();
    if (!selectedAnalyses.length) return toast.error("Selecione pelo menos uma análise de alergénio.");
    if (!activeProfile) return toast.error("Não foi possível identificar o analista a partir da sessão PIN.");
    const incomplete = samples.find((sample) => !sample.product.trim() || !sample.client.trim() || !sample.lot.trim() || !sample.result || (isElisa && !validElisaResult(sample.ppm)));
    if (incomplete) return toast.error(isElisa ? "Preencha produto, cliente, lote e um valor em ppm ou <L.Q. para todas as amostras." : "Preencha produto, cliente e lote para todas as amostras.");
    const samplesWithResult = samples.map((sample) => ({ ...sample, label: ANALYSIS_RESULTS.find((item) => item.value === sample.result)!.label, controlResult: ANALYSIS_RESULTS.find((item) => item.value === sample.result)!.controlResult, ppm: isElisa ? (isLimitOfQuantification(sample.ppm) ? "<L.Q." : Number(sample.ppm)) : null }));
    const result = samplesWithResult.some((sample) => sample.controlResult === "NC") ? "NC" : "C";
    const title = selectedAnalyses.length === 1 ? selectedAnalyses[0]?.test ?? "Análise interna" : `${selectedAnalyses.length} análises internas`;
    createEntry.mutate({ module: "internal_analysis", title, area: selectedCategories.join(", "), result, notes, payload: { category: selectedCategories.join(", "), test: selectedAnalyses[0]?.test ?? null, tests, analyses: selectedAnalyses, analyst: activeProfile.name, analystProfileId: activeProfile.id, samples: samplesWithResult, photos }, createNonconformity: false, severity: "medium" }, { onSuccess: () => { utils.quality.reports.invalidate(); setTests([]); setSamples([{ product: "", client: "", lot: "", result: "", ppm: "" }]); setNotes(""); setPhotos([]); } });
  }

  return <><ModuleHeader label="Análises internas" description="Registe a monitorização de alergénios por categoria, produto, cliente, resultado e evidência." icon={Microscope} commonToAllOperations /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Identificação da análise</CardTitle><CardDescription>Selecione uma ou mais análises. As amostras, observações e fotografias ficam associadas ao mesmo registo.</CardDescription></CardHeader><CardContent className="grid gap-4 md:grid-cols-[1.5fr_.75fr]"><div className="space-y-3"><Label>Categoria e análise</Label><div className="space-y-3 rounded-xl border border-slate-100 bg-slate-50/60 p-4">{ALLERGEN_ANALYSIS_CATEGORIES.map((category) => <div key={category.label}><p className="mb-2 text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">{category.label}</p><div className="flex flex-wrap gap-2">{category.tests.map((test) => <Button key={test} type="button" size="sm" variant={tests.includes(test) ? "default" : "outline"} onClick={() => toggleTest(test)}>{test}</Button>)}</div></div>)}</div><p className="text-xs text-muted-foreground">{tests.length ? `${tests.length} análise${tests.length === 1 ? "" : "s"} selecionada${tests.length === 1 ? "" : "s"}.` : "Selecione as análises que partilham o mesmo resultado e evidência."}</p></div><div className="space-y-2"><Label>Analista responsável</Label><Input readOnly value={activeProfile?.name ?? "Sessão PIN não identificada"} aria-label="Analista responsável" /></div></CardContent></Card><Card className="border-0 panel-shadow"><CardHeader><div className="flex items-start justify-between gap-4"><div><CardTitle>Amostras e cliente</CardTitle><CardDescription>Registe um ou mais produtos, cada um associado a um cliente, lote e resultado próprio.</CardDescription></div><Button type="button" size="sm" variant="outline" onClick={addSample}><Plus className="mr-1 h-3.5 w-3.5" />Amostra</Button></div></CardHeader><CardContent className="space-y-4">{samples.map((sample, index) => <div key={index} className="space-y-4 rounded-xl border border-slate-100 bg-slate-50/60 p-4"><div className="flex items-center justify-between"><p className="font-mono-ui text-xs font-semibold uppercase tracking-[0.12em] text-slate-500">Amostra {index + 1}</p><Button type="button" size="icon" variant="ghost" className="h-7 w-7 text-slate-500 hover:text-red-700" disabled={samples.length === 1} onClick={() => setSamples((current) => current.filter((_, sampleIndex) => sampleIndex !== index))}><Trash2 className="h-4 w-4" /></Button></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Produto / material</Label><Input required value={sample.product} onChange={(event) => updateSample(index, (current) => ({ ...current, product: event.target.value }))} placeholder="Produto ou matéria-prima" /></div><div className="space-y-2"><Label>Cliente</Label><Input required value={sample.client} onChange={(event) => updateSample(index, (current) => ({ ...current, client: event.target.value }))} placeholder="Nome do cliente" /></div><div className="space-y-2"><Label>Lote</Label><Input required value={sample.lot} onChange={(event) => updateSample(index, (current) => ({ ...current, lot: event.target.value }))} placeholder="Lote ou identificação" /></div></div><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Resultado</Label><Select value={sample.result} onValueChange={(value) => updateSample(index, (current) => ({ ...current, result: value as AnalysisResult }))}><SelectTrigger><SelectValue placeholder="Selecione o resultado" /></SelectTrigger><SelectContent>{ANALYSIS_RESULTS.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectContent></Select></div>{isElisa && <div className="space-y-2"><Label>Resultado Elisa (ppm ou &lt;L.Q.)</Label><Input required inputMode="decimal" value={sample.ppm} onChange={(event) => updateSample(index, (current) => ({ ...current, ppm: event.target.value }))} placeholder="Valor numérico ou <L.Q." /></div>}</div></div>)}</CardContent></Card><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Observações e evidências</CardTitle><CardDescription>As observações são obrigatórias; as fotografias selecionadas ficam associadas a todas as análises escolhidas.</CardDescription></CardHeader><CardContent className="space-y-5"><Notes value={notes} onChange={setNotes} required /><div className="space-y-3 rounded-xl border border-dashed border-teal-200 bg-teal-50/60 p-4"><div className="flex items-center gap-2 text-sm font-medium text-teal-900"><ImagePlus className="h-4 w-4" />Fotografias de evidência</div><Input aria-label="Adicionar fotografia de evidência" type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => addPhoto(event.target.files?.[0])} disabled={uploadPhoto.isPending || photos.length >= 5} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{photos.map((photo) => <div key={photo.url} className="relative overflow-hidden rounded-lg border border-teal-100 bg-white"><img src={photo.url} alt={`Evidência: ${photo.fileName}`} className="h-28 w-full object-cover" /><Button type="button" size="icon" variant="secondary" className="absolute right-2 top-2 h-7 w-7" aria-label={`Remover fotografia ${photo.fileName}`} onClick={() => setPhotos((current) => current.filter((item) => item.url !== photo.url))}><Trash2 className="h-3.5 w-3.5" /></Button><p className="truncate px-2 py-1 text-xs text-slate-600">{photo.fileName}</p></div>)}</div></div><Button className="w-full" size="lg" variant={samples.some((sample) => ANALYSIS_RESULTS.find((item) => item.value === sample.result)?.controlResult === "NC") ? "destructive" : "default"} disabled={createEntry.isPending || uploadPhoto.isPending || !tests.length || !activeProfile || samples.some((sample) => !sample.result)}>{createEntry.isPending ? "A registar…" : "Registar análises internas"}</Button></CardContent></Card></form></>;
}

const TEMPERATURE_EQUIPMENT_BY_FACTORY: Record<string, Array<{ id: string; name: string; area: string; limit: number }>> = {
  "1": [
    { id: "f1-freezer-1", name: "Equipamento de congelação 1", area: "Área da Qualidade", limit: -18 },
    { id: "f1-freezer-2", name: "Equipamento de congelação 2", area: "Área da Qualidade", limit: -18 },
  ],
  "2": [{ id: "f2-cold-room", name: "Câmara de Frio", area: "Câmara de Frio", limit: 10 }],
};
const AUTOMATIC_TEMPERATURE_PLATFORM_URL = "https://s31-iot.tekonelectronics.com/Login?returnUrl=%2FDashboard";

export function TemperatureControls({ createEntry }: any) {
  const { factoryId, factories } = useControlFactory();
  const equipment = TEMPERATURE_EQUIPMENT_BY_FACTORY[factoryId] ?? [];
  const factory = factories.find((item: any) => String(item.id) === factoryId);
  const [readings, setReadings] = useState<Record<string, { temperature: string; notes: string }>>({});
  const [evidencePhotos, setEvidencePhotos] = useState<VerificationEvidencePhoto[]>([]);
  const [historyStartDate, setHistoryStartDate] = useState("");
  const [historyEndDate, setHistoryEndDate] = useState("");
  const [historyEquipmentId, setHistoryEquipmentId] = useState("");
  const allEquipment = useMemo(() => Object.values(TEMPERATURE_EQUIPMENT_BY_FACTORY).flat(), []);
  const historyInput = useMemo(() => ({ startDate: historyStartDate ? new Date(`${historyStartDate}T12:00:00`) : undefined, endDate: historyEndDate ? new Date(`${historyEndDate}T12:00:00`) : undefined, equipmentId: historyEquipmentId || undefined }), [historyEndDate, historyEquipmentId, historyStartDate]);
  const history = trpc.quality.temperatureHistory.useQuery(historyInput);

  useEffect(() => { setReadings(Object.fromEntries((TEMPERATURE_EQUIPMENT_BY_FACTORY[factoryId] ?? []).map((item) => [item.id, { temperature: "", notes: "" }]))); }, [factoryId]);
  const updateReading = (id: string, field: "temperature" | "notes", value: string) => setReadings((current) => ({ ...current, [id]: { temperature: current[id]?.temperature ?? "", notes: current[id]?.notes ?? "", [field]: value } }));

  function submit(event: FormEvent) {
    event.preventDefault();
    if (!factoryId || !factory || !equipment.length) return toast.error("Selecione a Fábrica 1 ou a Fábrica 2 para este controlo.");
    const incomplete = equipment.some((item) => readings[item.id]?.temperature === "" || !Number.isFinite(Number(readings[item.id]?.temperature)));
    if (incomplete) return toast.error("Registe a temperatura medida em todos os equipamentos apresentados.");
    const items = equipment.map((item) => {
      const temperature = Number(readings[item.id]!.temperature);
      return { ...item, temperature, result: temperature <= item.limit ? "C" : "NC", notes: readings[item.id]!.notes.trim() || null };
    });
    if (items.some((item) => item.result === "NC" && !item.notes)) return toast.error("Inclua uma observação para cada equipamento fora do limite.");
    const result = items.some((item) => item.result === "NC") ? "NC" : "C";
    createEntry.mutate({ module: "temperature_controls", title: `Controlo de Temperatura — ${factory.name}`, area: Array.from(new Set(items.map((item) => item.area))).join(", "), result, notes: items.filter((item) => item.notes).map((item) => `${item.name}: ${item.notes}`).join(" · ") || undefined, payload: { equipment: items, evidencePhotos }, createNonconformity: false, severity: result === "NC" ? "high" : "low" });
  }

  const hasNc = equipment.some((item) => { const value = Number(readings[item.id]?.temperature); return readings[item.id]?.temperature !== "" && Number.isFinite(value) && value > item.limit; }); return <><ModuleHeader label="Controlos de Temperatura" description="Registe a temperatura dos equipamentos críticos e valide o cumprimento do limite definido." icon={ThermometerSnowflake} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardHeader><div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><CardTitle>Verificação manual por equipamento</CardTitle><CardDescription>Os limites são validados automaticamente: congelação ≤ -18 ºC e câmara de frio ≤ 10 ºC.</CardDescription></div><Button asChild type="button" variant="outline"><a href={AUTOMATIC_TEMPERATURE_PLATFORM_URL} target="_blank" rel="noreferrer"><ThermometerSnowflake className="mr-2 h-4 w-4" />Plataforma automática</a></Button></div></CardHeader><CardContent className="space-y-4">{!factoryId || !equipment.length ? <div className="rounded-xl border border-dashed border-sky-200 bg-sky-50/60 p-5 text-sm text-sky-900">Selecione a Fábrica 1 ou a Fábrica 2 no topo. Os restantes equipamentos serão consultados na plataforma de verificação automática.</div> : equipment.map((item) => { const reading = readings[item.id] ?? { temperature: "", notes: "" }; const temperature = reading.temperature === "" ? null : Number(reading.temperature); const result = temperature === null || !Number.isFinite(temperature) ? null : temperature <= item.limit ? "C" : "NC"; return <div key={item.id} className={`rounded-xl border p-4 ${result === "NC" ? "border-red-200 bg-red-50/60" : result === "C" ? "border-emerald-200 bg-emerald-50/50" : "border-slate-100 bg-slate-50/60"}`}><div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between"><div><p className="font-medium text-slate-950">{item.name}</p><p className="mt-1 text-sm text-muted-foreground">{item.area} · Limite: ≤ {item.limit} ºC</p></div>{result && <span className={`rounded-full px-3 py-1 text-xs font-semibold ${result === "C" ? "bg-emerald-100 text-emerald-800" : "bg-red-100 text-red-800"}`}>{result === "C" ? "Conforme" : "Fora do limite"}</span>}</div><div className="mt-4 grid gap-4 md:grid-cols-[minmax(0,240px)_1fr]"><div className="space-y-2"><Label htmlFor={`temperature-${item.id}`}>Temperatura medida (ºC)</Label><Input id={`temperature-${item.id}`} required type="number" step="0.1" value={reading.temperature} onChange={(event) => updateReading(item.id, "temperature", event.target.value)} placeholder="Ex.: -18,5" /></div><div className="space-y-2"><Label htmlFor={`temperature-note-${item.id}`}>Observações {result === "NC" ? "(obrigatórias)" : ""}</Label><Input id={`temperature-note-${item.id}`} required={result === "NC"} value={reading.notes} onChange={(event) => updateReading(item.id, "notes", event.target.value)} placeholder="Estado do equipamento, ação tomada ou observações" /></div></div></div>; })}{hasNc && <NcEvidenceUploader module="temperature_controls" photos={evidencePhotos} onChange={setEvidencePhotos} />}<Button className="w-full" size="lg" disabled={createEntry.isPending || !equipment.length}>{createEntry.isPending ? "A registar…" : "Registar controlo de temperatura"}</Button></CardContent></Card></form><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Consulta de resultados</CardTitle><CardDescription>Filtre os registos por intervalo de datas e equipamento.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 md:grid-cols-3"><div className="space-y-2"><Label>Data inicial</Label><Input aria-label="Data inicial de temperaturas" type="date" value={historyStartDate} onChange={(event) => { setHistoryStartDate(event.target.value); if (historyEndDate && event.target.value > historyEndDate) setHistoryEndDate(event.target.value); }} /></div><div className="space-y-2"><Label>Data final</Label><Input aria-label="Data final de temperaturas" type="date" min={historyStartDate} value={historyEndDate} onChange={(event) => setHistoryEndDate(event.target.value)} /></div><div className="space-y-2"><Label>Equipamento</Label><Select value={historyEquipmentId || "all"} onValueChange={(value) => setHistoryEquipmentId(value === "all" ? "" : value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os equipamentos</SelectItem>{allEquipment.map((item) => <SelectItem key={item.id} value={item.id}>{item.name} · {item.area}</SelectItem>)}</SelectContent></Select></div></div>{history.isLoading ? <p className="text-sm text-muted-foreground">A carregar resultados…</p> : history.data?.length ? <div className="divide-y overflow-hidden rounded-xl border border-slate-100">{history.data.map((item) => <div key={`${item.entryId}-${item.equipmentId}`} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-slate-950">{item.name}</p><p className="mt-1 text-sm text-muted-foreground">{item.area} · {new Date(item.completedAt).toLocaleDateString("pt-PT")} · {item.temperature ?? "—"} ºC</p>{item.notes ? <p className="mt-1 text-xs text-slate-600">{item.notes}</p> : null}</div><span className={`rounded-full px-3 py-1 text-xs font-semibold ${item.result === "NC" ? "bg-red-100 text-red-800" : "bg-emerald-100 text-emerald-800"}`}>{item.result === "NC" ? "NC" : "C"}</span></div>)}</div> : <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-5 text-sm text-slate-600">Sem resultados para os filtros selecionados.</div>}</CardContent></Card></>;
}

function FoodDefense({ createEntry, plannedTaskId }: { createEntry: any; plannedTaskId?: number }) {
  const { factoryId } = useControlFactory();
  const [assessments, setAssessments] = useState<Record<string, { result?: Result; notes: string; probability: string; severity: string; newMeasures: string; owner: string; deadline: string }>>({});
  const [evidencePhotos, setEvidencePhotos] = useState<VerificationEvidencePhoto[]>([]);
  const sections = useMemo(() => Array.from(new Set(FOOD_DEFENSE_CRITERIA.map((item) => item.section))), []);
  const assessment = (id: string) => assessments[id] ?? { result: undefined, notes: "", probability: "", severity: "", newMeasures: "", owner: "", deadline: "" };
  const update = (id: string, changes: Partial<ReturnType<typeof assessment>>) => setAssessments((current) => ({ ...current, [id]: { ...assessment(id), ...changes } }));
  const completed = FOOD_DEFENSE_CRITERIA.filter((item) => assessment(item.id).result).length;
  const ncItems = FOOD_DEFENSE_CRITERIA.filter((item) => assessment(item.id).result === "NC");
  const riskFor = (itemId: string) => { const value = assessment(itemId); const probability = Number(value.probability); const severity = Number(value.severity); if (!probability || !severity) return null; const vulnerability = probability * severity; return { vulnerability, guidance: FOOD_DEFENSE_RISK_GUIDANCE.find((item) => vulnerability >= item.min) ?? FOOD_DEFENSE_RISK_GUIDANCE.at(-1)! }; };
  const suggestMeasure = trpc.quality.suggestFoodDefenseMeasure.useMutation({
    onSuccess: (data, variables) => update(variables.itemId, { newMeasures: data.suggestion }),
    onError: (error) => toast.error(error.message),
  });
  const requestMeasureSuggestion = (item: typeof FOOD_DEFENSE_CRITERIA[number]) => {
    const value = assessment(item.id);
    const risk = riskFor(item.id);
    if (!factoryId) return toast.error("Selecione a fábrica para gerar a sugestão.");
    if (!risk) return toast.error("Selecione a probabilidade e a severidade antes de pedir uma sugestão.");
    suggestMeasure.mutate({ itemId: item.id, factoryId: Number(factoryId), criterion: item.criterion, section: item.section, notes: value.notes, probability: Number(value.probability), severity: Number(value.severity), vulnerability: risk.vulnerability, riskGuidance: `${risk.guidance.label}: ${risk.guidance.action}`, existingMeasure: value.newMeasures, plannedTaskId });
  };
  function submit(event: FormEvent) {
    event.preventDefault();
    if (completed !== FOOD_DEFENSE_CRITERIA.length) return toast.error("Conclua todos os critérios da checklist Food Defense antes de registar.");
    const incompleteRisk = ncItems.find((item) => { const value = assessment(item.id); return !value.probability || !value.severity; });
    if (incompleteRisk) return toast.error("Em cada NC indique probabilidade e severidade para calcular a vulnerabilidade.");
    const result = ncItems.length ? "NC" : "C";
    const criteria = FOOD_DEFENSE_CRITERIA.map((item) => { const value = assessment(item.id); const risk = riskFor(item.id); return { ...item, ...value, vulnerability: risk?.vulnerability ?? null, riskLevel: risk?.guidance.label ?? null, recommendedAction: risk?.guidance.action ?? null }; });
    createEntry.mutate({ module: "food_defense", title: "Food Defense — avaliação anual", area: "Food Defense", result, notes: ncItems.length ? `${ncItems.length} critério(s) NC identificado(s).` : "Checklist anual conforme.", payload: { periodicity: "annual", criteria, riskMatrix: "V = Probabilidade × Severidade", evidencePhotos }, createNonconformity: false, severity: ncItems.some((item) => (riskFor(item.id)?.vulnerability ?? 0) >= 6) ? "critical" : ncItems.length ? "high" : "low" });
  }
  return <><ModuleHeader label="Food Defense" description="Avaliação anual baseada na checklist de segurança, acessos, operações, fornecimentos e pessoal." icon={ShieldCheck} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Checklist anual Food Defense</CardTitle></CardHeader><CardContent><div className="flex flex-wrap gap-3"><Badge className="bg-slate-100 text-slate-800 hover:bg-slate-100">{completed} / {FOOD_DEFENSE_CRITERIA.length} critérios avaliados</Badge><Badge className={ncItems.length ? "bg-red-100 text-red-800 hover:bg-red-100" : "bg-emerald-100 text-emerald-800 hover:bg-emerald-100"}>{ncItems.length} NC</Badge></div></CardContent></Card>{sections.map((section, sectionIndex) => { const criteria = FOOD_DEFENSE_CRITERIA.filter((item) => item.section === section); const completeInSection = criteria.filter((item) => assessment(item.id).result).length; return <details key={section} open={sectionIndex === 0} className="overflow-hidden rounded-2xl border border-slate-200 bg-white panel-shadow"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 bg-slate-50 px-5 py-4"><div><p className="font-semibold text-slate-950">{section}</p><p className="mt-1 text-sm text-slate-600">{criteria.length} critérios · {completeInSection}/{criteria.length} avaliados</p></div><ChevronDown className="h-5 w-5 text-slate-500" /></summary><div className="space-y-4 p-4">{criteria.map((item, index) => { const value = assessment(item.id); const risk = riskFor(item.id); return <Card key={item.id} className={`border ${value.result === "NC" ? "border-red-200 bg-red-50/40" : "border-slate-100"}`}><CardContent className="space-y-4 p-4"><div className="flex gap-3"><span className="font-mono-ui h-6 shrink-0 rounded-md bg-slate-100 px-2 py-1 text-xs text-slate-700">{index + 1}</span><p className="font-medium text-slate-950">{item.criterion}</p></div><div className="space-y-2"><Label>Resultado da avaliação atual</Label><div className="grid grid-cols-3 gap-2">{(["C", "NC", "N/A"] as Result[]).map((result) => <Button key={result} type="button" variant={value.result === result ? result === "NC" ? "destructive" : "default" : "outline"} onClick={() => update(item.id, { result })}>{result}</Button>)}</div></div><Notes value={value.notes} onChange={(notes) => update(item.id, { notes })} />{value.result === "NC" && <div className="space-y-4 rounded-xl border border-red-200 bg-white/80 p-4"><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Probabilidade (P)</Label><Select value={value.probability} onValueChange={(probability) => update(item.id, { probability })}><SelectTrigger><SelectValue placeholder="1–3" /></SelectTrigger><SelectContent><SelectItem value="1">1 · Baixa</SelectItem><SelectItem value="2">2 · Média</SelectItem><SelectItem value="3">3 · Alta</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Severidade (S)</Label><Select value={value.severity} onValueChange={(severity) => update(item.id, { severity })}><SelectTrigger><SelectValue placeholder="1–3" /></SelectTrigger><SelectContent><SelectItem value="1">1 · Baixa</SelectItem><SelectItem value="2">2 · Média</SelectItem><SelectItem value="3">3 · Alta</SelectItem></SelectContent></Select></div><div className="rounded-lg border border-red-100 bg-red-50 p-3"><p className="text-xs font-medium text-red-900">Vulnerabilidade (V)</p><p className="mt-1 text-xl font-semibold text-red-950">{risk?.vulnerability ?? "—"}</p><p className="mt-1 text-xs leading-5 text-red-800">{risk?.guidance.label ?? "Selecione P e S"}</p></div></div>{risk && <p className="rounded-lg bg-amber-50 p-3 text-sm text-amber-950"><span className="font-semibold">Ação indicada:</span> {risk.guidance.action}</p>}<div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><div className="flex flex-wrap items-center justify-between gap-2"><Label>Nova medida de controlo</Label><Button type="button" size="sm" variant="outline" disabled={!risk || suggestMeasure.isPending} onClick={() => requestMeasureSuggestion(item)}><WandSparkles className="mr-2 h-4 w-4" />{suggestMeasure.isPending ? "A sugerir…" : "Sugerir com IA"}</Button></div><Textarea value={value.newMeasures} onChange={(event) => update(item.id, { newMeasures: event.target.value })} placeholder="Medida proposta ou sugestão gerada por IA" /><p className="text-xs leading-5 text-slate-500">A sugestão é editável e deve ser validada pela equipa antes do registo.</p></div><div className="space-y-2"><Label>Responsável</Label><Input value={value.owner} onChange={(event) => update(item.id, { owner: event.target.value })} placeholder="Responsável pela medida" /></div><div className="space-y-2"><Label>Prazo</Label><Input type="date" value={value.deadline} onChange={(event) => update(item.id, { deadline: event.target.value })} /></div></div></div>}</CardContent></Card>; })}</div></details>; })}{ncItems.length ? <NcEvidenceUploader module="food_defense" photos={evidencePhotos} onChange={setEvidencePhotos} /> : null}<Button className="w-full" size="lg" variant={ncItems.length ? "destructive" : "default"} disabled={createEntry.isPending}>{createEntry.isPending ? "A registar…" : ncItems.length ? "Registar avaliação Food Defense com NC" : "Registar avaliação Food Defense conforme"}</Button></form></>;
}

function SuggestionBoxes({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const { factories } = useControlFactory();
  const factory = factories.find((item: any) => String(item.id) === factoryId);
  const locations = suggestionLocationsForFactory(factory?.code);
  const [location, setLocation] = useState("");
  const [count, setCount] = useState("0");
  const [triage, setTriage] = useState("Por triagem");
  const [notes, setNotes] = useState("");

  useEffect(() => { setLocation(locations[0] ?? ""); }, [factory?.code]);
  function submit(event: FormEvent) { event.preventDefault(); if (!location) return; createEntry.mutate({ module: "suggestion_boxes", title: `Caixa de sugestões — ${location}`, area: location, notes, payload: { count: Number(count), triage }, createNonconformity: false, severity: "low" }); }
  return <><ModuleHeader label="Caixas de sugestões" description="Selecione a fábrica ou linha para ver apenas as caixas que lhe estão associadas." icon={Lightbulb} /><form onSubmit={submit}><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6">{!factoryId || !locations.length ? <div className="rounded-xl border border-dashed bg-slate-50 p-4 text-sm text-muted-foreground">Selecione Fábrica 1, Fábrica 2 ou Fábrica 3/SG no topo para registar a verificação de uma caixa de sugestões.</div> : <><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Localização</Label><Select value={location} onValueChange={setLocation}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{locations.map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>N.º de registos</Label><Input type="number" min="0" value={count} onChange={(event) => setCount(event.target.value)} /></div><div className="space-y-2"><Label>Estado de triagem</Label><Select value={triage} onValueChange={setTriage}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Por triagem", "Em análise", "Triada", "Fechada"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div></div><Notes value={notes} onChange={setNotes} /><Button className="w-full" size="lg">Registar verificação</Button></>}</CardContent></Card></form></>;
}

function FragileInspection({ createEntry }: any) {
  const items = trpc.quality.listFragileItems.useQuery(); const utils = trpc.useUtils(); const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Item adicionado ao inventário."); }, onError: (error) => toast.error(error.message) }); const [itemId, setItemId] = useState(""); const [state, setState] = useState("Íntegro"); const [notes, setNotes] = useState(""); const [dialogOpen, setDialogOpen] = useState(false); const [name, setName] = useState(""); const [location, setLocation] = useState(""); const [type, setType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Vidro"); const item = items.data?.find((entry) => String(entry.id) === itemId);
  function submitInspection(event: FormEvent) { event.preventDefault(); if (!item) return toast.error("Selecione um item do inventário."); if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência."); createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${item.name}`, area: item.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: item.id, state, containmentAction: notes }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" }); }
  function add(event: FormEvent) { event.preventDefault(); addItem.mutate({ name, location, itemType: type }); setDialogOpen(false); setName(""); setLocation(""); }
  return <><ModuleHeader label="Quebráveis" description="Inspecione os itens do inventário e associe a ação de contenção quando existir desvio." icon={Boxes} /><div className="flex justify-end"><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button variant="outline"><Plus className="mr-2 h-4 w-4" />Adicionar ao inventário</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Novo item quebrável</DialogTitle></DialogHeader><form onSubmit={add} className="space-y-4"><div className="space-y-2"><Label>Item</Label><Input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Luminária de proteção" /></div><div className="space-y-2"><Label>Localização</Label><Input required value={location} onChange={(event) => setLocation(event.target.value)} placeholder="Ex.: Produção T" /></div><div className="space-y-2"><Label>Tipo</Label><Select value={type} onValueChange={(value) => setType(value as any)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><Button className="w-full">Adicionar item</Button></form></DialogContent></Dialog></div><form onSubmit={submitInspection}><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Item do inventário</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder="Selecione o item" /></SelectTrigger><SelectContent>{items.data?.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} — {entry.location}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div></div><div className="space-y-2"><Label>Ação de contenção / observações</Label><Textarea value={notes} onChange={(event) => setNotes(event.target.value)} required={state !== "Íntegro"} placeholder="Obrigatório em caso de item danificado ou em falta." /></div><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"}>Registar inspeção</Button></CardContent></Card></form></>;
}

function FragileInspectionLegacy({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const [periodicity, setPeriodicity] = useState("all");
  const [area, setArea] = useState("all");
  const [itemId, setItemId] = useState("");
  const [state, setState] = useState("Íntegro");
  const [notes, setNotes] = useState("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [name, setName] = useState("");
  const [newLocation, setNewLocation] = useState("");
  const [newPeriodicity, setNewPeriodicity] = useState<"D" | "S" | "Q" | "M">("M");
  const [type, setType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Outro");
  const utils = trpc.useUtils();
  const listInput = useMemo(() => ({ factoryId: factoryId ? Number(factoryId) : undefined, periodicity: periodicity === "all" ? undefined : periodicity as "D" | "S" | "Q" | "M" }), [factoryId, periodicity]);
  const items = trpc.quality.listFragileItems.useQuery(listInput);
  const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de quebrável adicionado ao inventário."); }, onError: (error) => toast.error(error.message) });
  const availableAreas = Array.from(new Set((items.data ?? []).map((entry) => entry.location))).sort();
  const visibleItems = (items.data ?? []).filter((entry) => area === "all" || entry.location === area);
  const inventoryCount = factoryId ? visibleItems.length : 0;
  const item = visibleItems.find((entry) => String(entry.id) === itemId) ?? (items.data ?? []).find((entry) => String(entry.id) === itemId);
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  function submitInspection(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de registar a inspeção.");
    if (!item) return toast.error("Selecione um ponto de controlo.");
    if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência.");
    createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${item.name}`, area: item.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: item.id, state, containmentAction: notes, periodicity: item.periodicity, itemType: item.itemType, sourceSheet: item.sourceSheet }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" });
  }
  function add(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de criar um ponto.");
    addItem.mutate({ name, location: newLocation, factoryId: Number(factoryId), periodicity: newPeriodicity, itemType: type });
    setDialogOpen(false); setName(""); setNewLocation("");
  }
  return <><ModuleHeader label="Quebráveis" description="Selecione a fábrica, a periodicidade e a área para inspecionar os pontos importados dos registos operacionais." icon={Boxes} /><div className="flex flex-col gap-4 rounded-2xl border border-teal-100 bg-teal-50/70 p-5 md:flex-row md:items-end"><div className="flex-1"><p className="font-medium text-teal-950">Pontos de controlo importados</p><p className="mt-1 text-sm text-teal-800">O inventário reflete as áreas e frequências D, S, Q e M dos ficheiros de controlo de quebráveis.</p></div><Badge className="w-fit bg-teal-700 text-white hover:bg-teal-700">{factoryId ? `${inventoryCount} pontos disponíveis` : "Selecione a fábrica"}</Badge><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button variant="outline"><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Novo ponto quebrável</DialogTitle></DialogHeader><form onSubmit={add} className="space-y-4"><div className="space-y-2"><Label>Ponto de controlo</Label><Input required value={name} onChange={(event) => setName(event.target.value)} /></div><div className="space-y-2"><Label>Área</Label><Input required value={newLocation} onChange={(event) => setNewLocation(event.target.value)} /></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Periodicidade</Label><Select value={newPeriodicity} onValueChange={(value) => setNewPeriodicity(value as "D" | "S" | "Q" | "M")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Tipo</Label><Select value={type} onValueChange={(value) => setType(value as typeof type)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((itemType) => <SelectItem key={itemType} value={itemType}>{itemType}</SelectItem>)}</SelectContent></Select></div></div><Button className="w-full">Adicionar ponto</Button></form></DialogContent></Dialog></div><form onSubmit={submitInspection} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Periodicidade</Label><Select value={periodicity} onValueChange={(value) => { setPeriodicity(value); setArea("all"); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Área</Label><Select value={area} onValueChange={(value) => { setArea(value); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem>{availableAreas.map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Ponto de controlo</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder={factoryId ? "Selecione o ponto" : "Selecione a fábrica primeiro"} /></SelectTrigger><SelectContent>{visibleItems.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} · {entry.periodicity}</SelectItem>)}</SelectContent></Select></div></div>{item && <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-100 bg-slate-50 p-4"><Badge variant="outline">{item.itemType}</Badge><Badge className="bg-slate-900 text-white hover:bg-slate-900">{item.periodicity} — {periodLabel[item.periodicity]}</Badge><span className="text-sm text-muted-foreground">{item.location}</span></div>}<div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Ação de contenção / observações</Label><Textarea value={notes} onChange={(event) => setNotes(event.target.value)} required={state !== "Íntegro"} placeholder="Obrigatório em caso de item danificado ou em falta." /></div><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"} disabled={!factoryId || !item}>Registar inspeção</Button></CardContent></Card></form></>;
}

function fileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error("Não foi possível ler a imagem."));
    reader.readAsDataURL(file);
  });
}

export function FragileInspectionV2({ createEntry, factoryId, preselectedItemId = null, showHeader = true }: { createEntry: any; factoryId: string; preselectedItemId?: number | null; showHeader?: boolean }) {
  const metadata = trpc.quality.metadata.useQuery();
  const utils = trpc.useUtils();
  const [periodicity, setPeriodicity] = useState("all");
  const [area, setArea] = useState("all");
  const [itemId, setItemId] = useState(preselectedItemId ? String(preselectedItemId) : "");
  const [state, setState] = useState("Íntegro");
  const [notes, setNotes] = useState("");
  const [createOpen, setCreateOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [selectedFactoryId, setSelectedFactoryId] = useState("");
  const [selectedPeriodicity, setSelectedPeriodicity] = useState<"D" | "S" | "Q" | "M">("M");
  const [selectedType, setSelectedType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Outro");
  const factoryInput = useMemo(() => factoryId ? { factoryId: Number(factoryId) } : undefined, [factoryId]);
  const items = trpc.quality.listFragileItems.useQuery(factoryInput, { enabled: Boolean(factoryId) });
  const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de controlo criado."); setCreateOpen(false); }, onError: (error) => toast.error(error.message) });
  const updateItem = trpc.quality.updateFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de controlo atualizado."); }, onError: (error) => toast.error(error.message) });
  const uploadImage = trpc.quality.uploadFragileReferenceImage.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Imagem de referência carregada."); }, onError: (error) => toast.error(error.message) });
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  const factoryItems = items.data ?? [];
  const availableAreas = Array.from(new Set(factoryItems.map((entry) => entry.location))).sort();
  const visibleItems = factoryItems.filter((entry) => (periodicity === "all" || entry.periodicity === periodicity) && (area === "all" || entry.location === area));
  const selectedItem = visibleItems.find((entry) => String(entry.id) === itemId) ?? factoryItems.find((entry) => String(entry.id) === itemId);
  const factories = metadata.data?.factories ?? [];

  function resetEditor(entry?: any) {
    setEditing(entry ?? null);
    setName(entry?.name ?? "");
    setLocation(entry?.location ?? factoryItems[0]?.location ?? "");
    setSelectedFactoryId(String(entry?.factoryId ?? factoryId ?? ""));
    setSelectedPeriodicity(entry?.periodicity ?? "M");
    setSelectedType(entry?.itemType ?? "Outro");
  }

  function openCreate() { resetEditor(); setSelectedFactoryId(factoryId); setCreateOpen(true); }
  function openEdit(entry: any) { resetEditor(entry); setEditOpen(true); }

  function saveNew(event: FormEvent) {
    event.preventDefault();
    if (!selectedFactoryId) return toast.error("Selecione a fábrica do novo ponto.");
    if (!location) return toast.error("Selecione a área do novo ponto.");
    addItem.mutate({ name, location, factoryId: Number(selectedFactoryId), periodicity: selectedPeriodicity, itemType: selectedType });
  }

  function saveEdit(event: FormEvent) {
    event.preventDefault();
    if (!editing) return;
    if (!selectedFactoryId) return toast.error("Selecione a fábrica do ponto de controlo.");
    if (!location) return toast.error("Selecione a área do ponto de controlo.");
    updateItem.mutate({ id: editing.id, name, location, factoryId: Number(selectedFactoryId), periodicity: selectedPeriodicity, itemType: selectedType }, { onSuccess: () => setEditOpen(false) });
  }

  async function addReferenceImage(file?: File) {
    if (!file || !editing) return;
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return toast.error("Use uma imagem JPG, PNG ou WEBP.");
    if (file.size > 4_500_000) return toast.error("A imagem deve ter no máximo 4,5 MB.");
    try {
      const dataUrl = await fileAsDataUrl(file);
      uploadImage.mutate({ itemId: editing.id, fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataUrl }, { onSuccess: (result) => setEditing((current: any) => current ? { ...current, referenceImageUrl: result.url, referenceImageName: file.name } : current) });
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível carregar a imagem."); }
  }

  function submitInspection(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de registar a inspeção.");
    if (!selectedItem) return toast.error("Selecione um ponto de controlo.");
    if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência.");
    createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${selectedItem.name}`, area: selectedItem.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: selectedItem.id, state, containmentAction: notes, periodicity: selectedItem.periodicity, referenceImageUrl: selectedItem.referenceImageUrl }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" });
  }

  const pointForm = (onSubmit: (event: FormEvent) => void, submitLabel: string, includeImage = false) => <form onSubmit={onSubmit} className="space-y-4"><div className="space-y-2"><Label>Nome do ponto de controlo</Label><Input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Proteção acrílica da fatiadora" /></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Fábrica / linha</Label><Select value={selectedFactoryId} onValueChange={(value) => { setSelectedFactoryId(value); setLocation(factoryItems[0]?.location ?? ""); }}><SelectTrigger><SelectValue placeholder="Selecione a fábrica" /></SelectTrigger><SelectContent>{factories.map((factory) => <SelectItem key={factory.id} value={String(factory.id)}>{factory.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Área</Label><Select value={location} onValueChange={setLocation} disabled={!selectedFactoryId || !availableAreas.length}><SelectTrigger><SelectValue placeholder={selectedFactoryId ? "Selecione a área" : "Selecione primeiro a fábrica"} /></SelectTrigger><SelectContent>{availableAreas.map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Periodicidade</Label><Select value={selectedPeriodicity} onValueChange={(value) => setSelectedPeriodicity(value as "D" | "S" | "Q" | "M")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Tipo</Label><Select value={selectedType} onValueChange={(value) => setSelectedType(value as "Vidro" | "Plástico rígido" | "Outro")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((type) => <SelectItem key={type} value={type}>{type}</SelectItem>)}</SelectContent></Select></div></div>{includeImage && <div className="space-y-3 rounded-xl border border-dashed border-teal-200 bg-teal-50/60 p-4"><div className="flex items-center gap-2 text-sm font-medium text-teal-900"><ImagePlus className="h-4 w-4" />Imagem de referência</div>{editing?.referenceImageUrl && <img src={editing.referenceImageUrl} alt={`Referência: ${editing.name}`} className="h-32 w-full rounded-lg border border-teal-100 object-cover" />}<Input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => addReferenceImage(event.target.files?.[0])} disabled={uploadImage.isPending} /><p className="text-xs text-teal-800">JPG, PNG ou WEBP, até 4,5 MB. A imagem fica associada a este ponto de controlo.</p></div>}<Button className="w-full" disabled={addItem.isPending || updateItem.isPending}>{addItem.isPending || updateItem.isPending ? "A guardar…" : submitLabel}</Button></form>;

  return <>{showHeader && <ModuleHeader label="Quebráveis" description="Gira os pontos por fábrica e área, incluindo a periodicidade e a imagem de referência de cada inspeção." icon={Boxes} />}<div className="flex flex-col gap-4 rounded-2xl border border-teal-100 bg-teal-50/70 p-5 md:flex-row md:items-end"><div className="flex-1"><p className="font-medium text-teal-950">Catálogo operacional de pontos</p><p className="mt-1 text-sm text-teal-800">Selecione uma fábrica para consultar, criar ou editar os pontos de controlo associados.</p></div><Badge className="w-fit bg-teal-700 text-white hover:bg-teal-700">{factoryId ? `${factoryItems.length} pontos na fábrica` : "Selecione a fábrica"}</Badge><Button variant="outline" onClick={openCreate}><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></div><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card className="border-0 panel-shadow"><CardHeader><CardTitle className="flex items-center gap-2"><MapPin className="h-5 w-5 text-teal-700" />Gerir pontos de controlo</CardTitle><CardDescription>Filtre os pontos da fábrica selecionada e edite o respetivo contexto operacional.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Select value={periodicity} onValueChange={(value) => { setPeriodicity(value); setArea("all"); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select><Select value={area} onValueChange={(value) => { setArea(value); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem>{availableAreas.map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div>{!factoryId ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Selecione a fábrica no topo para listar os pontos de controlo.</p> : <div className="max-h-[420px] space-y-2 overflow-y-auto pr-1">{visibleItems.slice(0, 40).map((entry) => <div key={entry.id} className="flex items-center gap-3 rounded-xl border border-slate-100 bg-white p-3"><div className="h-11 w-11 shrink-0 overflow-hidden rounded-lg bg-teal-50 text-teal-700">{entry.referenceImageUrl ? <img src={entry.referenceImageUrl} alt="" className="h-full w-full object-cover" /> : <ImagePlus className="m-3 h-5 w-5" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{entry.name}</p><p className="mt-0.5 truncate text-xs text-muted-foreground">{entry.location} · {entry.periodicity} — {periodLabel[entry.periodicity]}</p></div><Button type="button" size="icon" variant="outline" aria-label={`Editar ${entry.name}`} onClick={() => openEdit(entry)}><Pencil className="h-4 w-4" /></Button></div>)}{visibleItems.length > 40 && <p className="px-2 py-1 text-xs text-muted-foreground">Mostram-se os primeiros 40 pontos. Use os filtros para restringir a lista.</p>}{!visibleItems.length && <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Não existem pontos com estes filtros.</p>}</div>}</CardContent></Card><form onSubmit={submitInspection}><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Registar inspeção</CardTitle><CardDescription>O ponto selecionado transporta a fábrica, área e periodicidade para o registo.</CardDescription></CardHeader><CardContent className="space-y-5"><div className="space-y-2"><Label>Ponto de controlo</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder={factoryId ? "Selecione o ponto" : "Selecione a fábrica primeiro"} /></SelectTrigger><SelectContent>{visibleItems.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} · {entry.periodicity}</SelectItem>)}</SelectContent></Select></div>{selectedItem && <div className="space-y-3 rounded-xl border border-teal-100 bg-teal-50/50 p-4">{selectedItem.referenceImageUrl && <img src={selectedItem.referenceImageUrl} alt={`Referência de ${selectedItem.name}`} className="h-32 w-full rounded-lg object-cover" />}<div className="flex flex-wrap gap-2"><Badge variant="outline">{selectedItem.itemType}</Badge><Badge className="bg-slate-900 text-white hover:bg-slate-900">{selectedItem.periodicity} — {periodLabel[selectedItem.periodicity]}</Badge><span className="text-sm text-muted-foreground">{selectedItem.location}</span></div></div>}<div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><Notes value={notes} onChange={setNotes} required={state !== "Íntegro"} /><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"} disabled={!factoryId || !selectedItem}>Registar inspeção</Button></CardContent></Card></form></div><Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent><DialogHeader><DialogTitle>Adicionar ponto de controlo</DialogTitle><DialogDescription>Crie um ponto, indicando a fábrica, área, periodicidade e tipo de material.</DialogDescription></DialogHeader>{pointForm(saveNew, "Criar ponto de controlo")}</DialogContent></Dialog><Dialog open={editOpen} onOpenChange={setEditOpen}><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar ponto de controlo</DialogTitle><DialogDescription>Atualize os dados operacionais e associe uma imagem de referência opcional.</DialogDescription></DialogHeader>{pointForm(saveEdit, "Guardar alterações", true)}</DialogContent></Dialog></>;
}

function FragileInspectionDashboard({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const [periodicity, setPeriodicity] = useState("all");
  const [preselectedItemId, setPreselectedItemId] = useState<number | null>(null);
  const pendingInput = useMemo(() => factoryId ? { factoryId: Number(factoryId) } : undefined, [factoryId]);
  const pending = trpc.quality.fragilePending.useQuery(pendingInput, { enabled: Boolean(factoryId) });
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  const points = (pending.data ?? []).filter((point) => periodicity === "all" || point.periodicity === periodicity);
  const counts = (pending.data ?? []).reduce<Record<"D" | "S" | "Q" | "M", number>>((result, point) => { result[point.periodicity] += 1; return result; }, { D: 0, S: 0, Q: 0, M: 0 });
  const openInspection = (itemId: number) => { setPreselectedItemId(itemId); requestAnimationFrame(() => document.getElementById("registo-quebraveis")?.scrollIntoView({ behavior: "smooth", block: "start" })); };

  const unifiedIntro = <div className="rounded-2xl border border-teal-100 bg-teal-50/70 p-5"><div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="font-mono-ui text-xs uppercase tracking-[0.16em] text-teal-700">Gestão operacional</p><h2 className="mt-1 text-lg font-semibold text-teal-950">Pendências e catálogo de pontos</h2><p className="mt-1 text-sm text-teal-800">Filtre a periodicidade, priorize inspeções em falta e consulte ou edite os pontos da fábrica selecionada no mesmo fluxo.</p></div><Select value={periodicity} onValueChange={setPeriodicity}><SelectTrigger className="w-full bg-white md:w-52"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div>{factoryId && <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{Object.entries(periodLabel).map(([code, label]) => <div key={code} className="rounded-xl border border-teal-100 bg-white p-3"><p className="font-mono-ui text-xs text-muted-foreground">{code} · {label}</p><p className="mt-1 text-2xl font-semibold text-slate-900">{counts[code as "D" | "S" | "Q" | "M"]}</p><p className="text-xs text-muted-foreground">pendentes</p></div>)}</div>}</div>;

  return <div className="space-y-6"><ModuleHeader label="Quebráveis" description="Centralize as pendências, o catálogo e o registo de inspeções num único fluxo operacional." icon={Boxes} />{unifiedIntro}<Card className="border-0 panel-shadow"><CardHeader><CardTitle className="flex items-center gap-2"><CalendarClock className="h-5 w-5 text-teal-700" />Inspeções pendentes</CardTitle><CardDescription>Registe diretamente os pontos em falta; o catálogo completo e a edição encontram-se na continuação desta mesma área.</CardDescription></CardHeader><CardContent>{!factoryId ? <div className="rounded-xl border border-dashed bg-slate-50 p-5 text-sm text-muted-foreground">Selecione uma fábrica ou linha no topo para calcular as inspeções pendentes.</div> : pending.isLoading ? <p className="py-5 text-sm text-muted-foreground">A calcular pendências…</p> : points.length ? <div className="divide-y rounded-xl border border-slate-100">{points.map((point) => <div key={point.id} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-medium">{point.name}</p><Badge className="bg-slate-900 text-white hover:bg-slate-900">{point.periodicity} — {periodLabel[point.periodicity]}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{point.location} · {point.lastInspectionAt ? `Última inspeção: ${new Date(point.lastInspectionAt).toLocaleDateString("pt-PT")}` : "Sem inspeções registadas"}</p></div><Button onClick={() => openInspection(point.id)}><ClipboardCheck className="mr-2 h-4 w-4" />Registar inspeção</Button></div>)}</div> : <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-5 text-sm text-emerald-900"><CheckCircle2 className="mr-2 inline h-4 w-4" />Não existem pontos pendentes para os filtros selecionados.</div>}</CardContent></Card><div id="registo-quebraveis"><FragileInspectionV2 key={preselectedItemId ?? "sem-selecao"} createEntry={createEntry} factoryId={factoryId} preselectedItemId={preselectedItemId} showHeader={false} /></div></div>;
}
